const BACKGROUND_JOBS = new Map();
const MAX_BACKGROUND_JOBS = 80;
const BACKGROUND_JOB_TTL_MS = 45 * 60 * 1000;

function backgroundJobId(type) {
  return `${type}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
}

function pruneBackgroundJobs() {
  const now = Date.now();
  const jobs = [...BACKGROUND_JOBS.values()].sort((a, b) => a.createdAtMs - b.createdAtMs);
  jobs.forEach((job) => {
    if (job.status !== "running" && now - job.updatedAtMs > BACKGROUND_JOB_TTL_MS) {
      BACKGROUND_JOBS.delete(job.id);
    }
  });

  const remaining = [...BACKGROUND_JOBS.values()].sort((a, b) => a.createdAtMs - b.createdAtMs);
  while (remaining.length > MAX_BACKGROUND_JOBS) {
    const job = remaining.shift();
    if (job?.status !== "running") BACKGROUND_JOBS.delete(job.id);
    else remaining.push(job);
    if (remaining.every((item) => item.status === "running")) break;
  }
}

function publicBackgroundJob(job, includeResult = true) {
  if (!job) return null;
  return {
    id: job.id,
    type: job.type,
    status: job.status,
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
    completedAt: job.completedAt || null,
    statusPath: job.statusPath,
    result: includeResult && job.status === "success" ? job.result : null,
    error: includeResult && job.status === "failed" ? job.error : null,
  };
}

function createBackgroundJob(type, payload, runner, statusPathForId) {
  pruneBackgroundJobs();
  const id = backgroundJobId(type);
  const now = Date.now();
  const job = {
    id,
    type,
    status: "running",
    createdAtMs: now,
    updatedAtMs: now,
    createdAt: new Date(now).toISOString(),
    updatedAt: new Date(now).toISOString(),
    completedAt: "",
    statusPath: statusPathForId(id),
    result: null,
    error: null,
  };
  BACKGROUND_JOBS.set(id, job);

  Promise.resolve()
    .then(() => runner(payload))
    .then((result) => {
      const completedAt = Date.now();
      job.status = "success";
      job.result = result;
      job.updatedAtMs = completedAt;
      job.updatedAt = new Date(completedAt).toISOString();
      job.completedAt = job.updatedAt;
    })
    .catch((error) => {
      const completedAt = Date.now();
      job.status = "failed";
      job.error = {
        message: error?.message || "Background job failed",
        details: error?.details || null,
        callRecord: error?.callRecord || null,
        statusCode: error?.statusCode || 500,
      };
      job.updatedAtMs = completedAt;
      job.updatedAt = new Date(completedAt).toISOString();
      job.completedAt = job.updatedAt;
    });

  return job;
}

async function handleBackgroundJobStart(req, res, type, runner, statusPathForId) {
  try {
    const payload = await readJsonBody(req);
    const job = createBackgroundJob(type, payload, runner, statusPathForId);
    sendJson(res, 202, {
      ok: true,
      jobId: job.id,
      status: job.status,
      job: publicBackgroundJob(job, false),
    });
  } catch (error) {
    const status = error.statusCode && error.statusCode >= 400 && error.statusCode < 600 ? error.statusCode : 500;
    sendJson(res, status, {
      ok: false,
      error: error.message || "Background job start failed",
      details: error.details || null,
    });
  }
}

function handleBackgroundJobStatus(res, jobId) {
  pruneBackgroundJobs();
  const job = BACKGROUND_JOBS.get(jobId);
  if (!job) {
    sendJson(res, 404, {
      ok: false,
      error: "Background job not found",
    });
    return;
  }
  sendJson(res, 200, {
    ok: true,
    jobId: job.id,
    status: job.status,
    job: publicBackgroundJob(job, true),
  });
}

function envValue(names = []) {
  for (const name of names) {
    const value = process.env[name];
    if (value) return value;
  }
  return "";
}

function providerKeyStatus(provider) {
  const keyEnv = Array.isArray(provider.keyEnv) ? provider.keyEnv : [];
  const serverKeyEnv = keyEnv.find((name) => Boolean(process.env[name])) || "";
  return {
    hasServerKey: Boolean(serverKeyEnv),
    serverKeyEnv,
    keyEnv,
  };
}

function normalizeBaseUrl(value) {
  return String(value || "").trim().replace(/\/+$/, "");
}

function providerSignatureText(modelConfig = {}) {
  const source = modelConfig && typeof modelConfig === "object" ? modelConfig : {};
  return [
    source.provider,
    source.providerId,
    source.providerName,
    source.name,
    source.model,
    source.baseUrl,
    source.endpoint,
    source.apiMode,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function providerIdFromExplicitValue(value) {
  const source = String(value || "").trim().toLowerCase();
  if (!source) return "";
  const exactId = Object.keys(PROVIDERS).find((id) => source === id);
  if (exactId) return exactId;
  const exactName = Object.entries(PROVIDERS).find(([, provider]) => source === provider.name.toLowerCase());
  return exactName?.[0] || "";
}

function providerIdFromSignature(source) {
  const text = String(source || "").toLowerCase();
  if (!text) return "";
  if (/generativelanguage\.googleapis\.com|\bgemini[-_\s]/i.test(text)) return "gemini";
  if (/api\.deepseek\.com|\bdeepseek[-_\s]/i.test(text)) return "deepseek";
  if (/api\.moonshot\.(?:cn|ai)|\bkimi[-_\s]|\bmoonshot[-_\s]/i.test(text)) return "kimi";
  if (/api\.minimax(?:i)?\.(?:com|cn|io)|\bminimax[-_\s]/i.test(text)) return "minimax";
  if (/anthropic\.com|\bclaude[-_\s]/i.test(text)) return "claude";
  if (/api\.openai\.com|\bgpt[-_\s]|\bo[0-9]/i.test(text)) return "openai";
  return "";
}

function inferProviderId(modelConfig = {}) {
  const source = modelConfig && typeof modelConfig === "object" ? modelConfig : {};
  const explicit =
    providerIdFromExplicitValue(source.provider) ||
    providerIdFromExplicitValue(source.providerId) ||
    providerIdFromExplicitValue(source.providerName) ||
    providerIdFromExplicitValue(source.name);
  const inferred = providerIdFromSignature(providerSignatureText(source));

  if (explicit && !(explicit === "openai" && inferred && inferred !== "openai")) return explicit;
  return inferred || explicit || "openai";
}

function normalizeProviderBaseUrl(providerId, value) {
  const baseUrl = normalizeBaseUrl(value);
  if (!["minimax", "kimi", "gemini"].includes(providerId)) return baseUrl;

  try {
    const target = new URL(baseUrl);
    if (providerId === "minimax" && ["api.minimaxi.cn", "api.minimax.io"].includes(target.hostname)) {
      return MINIMAX_CN_BASE_URL;
    }
    if (providerId === "kimi" && target.hostname === "api.moonshot.ai") {
      return KIMI_CN_BASE_URL;
    }
    if (providerId === "gemini" && target.hostname === "generativelanguage.googleapis.com") {
      if (target.pathname === "/" || target.pathname === "/v1beta") return GEMINI_OPENAI_BASE_URL;
      if (target.pathname === "/v1beta/openai/") return GEMINI_OPENAI_BASE_URL;
    }
  } catch (error) {
    return baseUrl;
  }

  if (providerId === "minimax") {
    return baseUrl === MINIMAX_CN_TYPED_ALIAS_BASE_URL || baseUrl === MINIMAX_GLOBAL_BASE_URL ? MINIMAX_CN_BASE_URL : baseUrl;
  }

  return baseUrl === KIMI_GLOBAL_BASE_URL ? KIMI_CN_BASE_URL : baseUrl;
}

function canonicalModelKey(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function normalizeProviderModel(providerId, value) {
  const preset = PROVIDERS[providerId] || PROVIDERS.openai;
  const raw = String(value || "").trim();
  if (!raw) return preset.model;
  const knownModels = preset.models || [preset.model];
  if (knownModels.includes(raw)) return raw;

  const key = canonicalModelKey(raw);
  const inferredProvider = providerIdFromSignature(raw);
  if (inferredProvider && inferredProvider !== providerId) return preset.model;
  const known = knownModels.find((model) => canonicalModelKey(model) === key);
  if (known) return known;
  if (providerId === "gemini" && GEMINI_MODEL_ALIASES[key]) return GEMINI_MODEL_ALIASES[key];
  return raw;
}

function isGeminiFlashThinkingModel(model) {
  return /^gemini-(?:2\.5|3(?:\.\d+)?)-flash(?:-|$)/i.test(String(model || ""));
}

function canFallbackGeminiModel(config = {}) {
  return config.provider === "gemini" && config.model && config.model !== GEMINI_DEFAULT_MODEL && !/^https?:\/\//i.test(config.endpoint || "");
}

function isKimiFixedTemperatureModel(model) {
  return /^kimi-k2\.(?:6|5)\b/i.test(String(model || ""));
}

function kimiTemperatureForModel(model) {
  return isKimiFixedTemperatureModel(model) ? 0.6 : 1;
}

function normalizeTemperature(providerId, value, model = "") {
  if (providerId === "kimi") return kimiTemperatureForModel(model);
  if (!Number.isFinite(value)) return 0.4;
  if (providerId === "minimax") {
    return Math.min(Math.max(value, 0.01), 1);
  }
  return Math.min(Math.max(value, 0), 2);
}

