function generatedComponentViolatesFamily(component, payload = {}) {
  const requestedFamily = oneOfComponentFamily(payload.family, "");
  const modelFamily = oneOfComponentFamily(component?.modelFamily, "");
  const family = oneOfComponentFamily(component?.family || requestedFamily);
  const source = `${component?.name || ""} ${component?.description || ""} ${component?.html || ""}`;
  if (requestedFamily && requestedFamily !== "ClientHomeAtoms" && modelFamily && modelFamily !== requestedFamily) {
    return true;
  }
  if (family === "PammProducts") {
    const hasPammSemantics = /PAMM|资管|产品|策略|年化|收益|规模|跟投|风险|排行|yield|portfolio|managed/i.test(source);
    const looksLikeCopytrading = /CopyTrading|跟单|信号源|signal|follow/i.test(source);
    const looksLikeOnboarding = /KYC|开户|开真实账户|创建真实账户|首次入金|身份认证|onboarding|deposit progress/i.test(source);
    return !hasPammSemantics || looksLikeCopytrading || looksLikeOnboarding;
  }
  if (family === "CopytradingSignals") {
    const hasSignalSemantics = /CopyTrading|跟单|信号源|signal|收益率|总收益|最大回撤|回撤|订阅|关注|跟单|curve|trend/i.test(source);
    const looksLikeOnboarding = /KYC|开户|开真实账户|创建真实账户|首次入金|身份认证|账户开通进度|onboarding|deposit progress/i.test(source);
    const looksLikePamm = /PAMM|资管产品|产品推荐|年化|跟投规模/i.test(source);
    return !hasSignalSemantics || looksLikeOnboarding || looksLikePamm;
  }
  if (family === "RiskDisclosure") {
    const hasRiskSemantics = /风险|风险披露|合规|免责声明|保证金|杠杆|强平|亏损|Risk|Disclosure|Margin|Leverage|Loss/i.test(source);
    const looksLikeAccountOverview = /Account Overview|Wallet Balance|Trading Balance|Total Assets|Deposit|Open Account|账户概览|资产概览|钱包余额|交易余额/i.test(source);
    return !hasRiskSemantics || looksLikeAccountOverview;
  }
  if (family === "SupportContact") {
    const hasSupportSemantics = /在线客服|联系客服|客服|客户经理|服务时间|帮助中心|工单|实时对话|Support|Contact|Ticket|Live Chat|Manager|Service Hours/i.test(source);
    const leaksPrompt = /首页目标|当前步骤|slot：|模块名称：|Client Home Atom/i.test(source);
    const looksLikeAccountOverview = /Account Overview|Wallet Balance|Trading Balance|Total Assets|KYC Verified|Open Account|账户概览|资产概览|钱包余额|交易余额|开真实账户/i.test(source);
    return !hasSupportSemantics || leaksPrompt || looksLikeAccountOverview;
  }
  if (family === "WelcomeHeader" && promptRequestsStrictWelcomeHeader(payload)) {
    const hasWelcomeSemantics = /张明|姓名|客户|用户|昵称|早安|午安|晚安|欢迎|问候|最近登录|上次登录|Last\s*login|Login\s*time/i.test(source);
    const leaksConversionModule = /身份认证|KYC|真实账户|首次入金|总资产|钱包余额|资产概览|入金|开户|活动|营销|奖励|推广|CopyTrading|去完成/i.test(source);
    return !hasWelcomeSemantics || leaksConversionModule;
  }
  return false;
}

function generatedComponentExplicitScore(component, payload = {}) {
  const score = component?.score ?? payload.componentScore;
  return Number.isFinite(Number(score)) ? normalizeComponentScore(score, COMPONENT_REFERENCE_SCORE_POLICY.blockedMax) : null;
}

function generatedComponentHasChartEvidence(component) {
  const html = String(component?.html || "");
  const css = String(component?.css || "");
  const source = `${html} ${css}`;
  return /<svg\b|<path\b|<polyline\b|<canvas\b|data-home-echart|data-chart|sparkline|curve|trend|chart-line|area-chart|走势图|曲线|趋势/i.test(source);
}

function generatedComponentHasVisiblePlaceholder(component) {
  const html = String(component?.html || "");
  const css = String(component?.css || "");
  const source = `${html} ${css}`;
  return (
    /\b(?:chart|curve|trend|signal|sparkline)[\w-]*placeholder\b|\bplaceholder[\w-]*(?:chart|curve|trend|signal|sparkline)\b/i.test(source) ||
    /home-chart-placeholder-bg|chart-placeholder-bg|signal-chart-placeholder/i.test(source) ||
    /灰色占位|空图表|图表占位|待生成图表|chart\s+placeholder|empty\s+chart/i.test(source)
  );
}

function generatedComponentUsesBrokenIconFont(component) {
  const html = String(component?.html || "");
  const css = String(component?.css || "");
  return /<i\b[^>]*>\s*<\/i>/i.test(html) && /content\s*:\s*["']\\(?:e[0-9a-f]{3}|[0-9a-f]{4})/i.test(css);
}

function generatedComponentVisibleText(component) {
  return stripHtmlTags(component?.html || "");
}

function componentReferenceReleaseIssues(component, payload = {}) {
  const family = oneOfComponentFamily(component?.family || payload.family, "");
  const visibleText = cleanText(component?.visibleText || generatedComponentVisibleText(component), "", 600);
  const rendererText = cleanText(stripHtmlTags(component?.rendererHtml || component?.html || ""), "", 600);
  const source = `${visibleText} ${rendererText} ${component?.name || ""} ${component?.description || ""}`;
  const issues = [];

  if (/Invite\s+Link\s+First|Link,\s*invite\s+code|conversion\s+metrics\s+stay\s+visible/i.test(source)) {
    issues.push("组件参考含英文模板文案，不能作为中文首页发布参考。");
  }
  if (/--\s*(?:Opens|Accounts|Clicks|Registrations|点击|账户|开户|注册)\b/i.test(source) || /(?:^|\s)--(?:\s|$).*(?:^|\s)--(?:\s|$)/.test(source)) {
    issues.push("组件参考含 -- 空数据占位，不能作为高分兜底 renderer。");
  }
  if (/\b(?:Primary Action|Lorem ipsum|Sample Data|AI\s+Style|Untitled Module)\b/i.test(source)) {
    issues.push("组件参考含通用模板占位文案，不能进入可发布首页。");
  }
  if (family === "ReferralLinkCard" && !/(推广链接|开户链接|邀请|邀请码|复制|inviteUrl|inviteCode|referral)/i.test(source)) {
    issues.push("ReferralLinkCard 缺少推广链接、邀请码或复制动作语义。");
  }

  return [...new Set(issues)].slice(0, 4);
}

function generatedComponentQualityIssues(component, payload = {}) {
  const family = oneOfComponentFamily(component?.family || payload.family);
  const issues = [];
  const explicitScore = generatedComponentExplicitScore(component, payload);
  const source = `${component?.name || ""} ${component?.description || ""} ${component?.html || ""} ${component?.css || ""}`;
  componentReferenceReleaseIssues(component, payload).forEach((issue) => issues.push(issue));
  if (explicitScore != null && explicitScore <= COMPONENT_REFERENCE_SCORE_POLICY.blockedMax) {
    issues.push(`组件评分 ${explicitScore}/10 属于阻断档，不能作为当前 slot 填充或后续参考。`);
  }
  if (["AccountPerformance", "CopytradingSignals", "PammProducts"].includes(family)) {
    if (generatedComponentHasVisiblePlaceholder(component)) {
      issues.push("图表型组件包含可见 chart/curve placeholder，占位会在首页渲染成空灰块。");
    }
    if (!generatedComponentHasChartEvidence(component)) {
      issues.push("图表型组件缺少 SVG/canvas/data-chart/趋势结构证据。");
    }
  }
  if (family === "QuickActions" && generatedComponentUsesBrokenIconFont(component)) {
    issues.push("快捷入口使用空 i 标签和私有 iconfont content，当前页面没有加载对应字体，会渲染成空图标。");
  }
  // 布局缺陷门禁：这些写法会在首页栅格容器里留下大块空白/塌缩/溢出，命中即判不合格并回退积木库。
  const css = String(component?.css || "");
  const layoutFamilies = ["QuickActions", "TradingAccounts", "OnboardingProgress", "WalletList"];
  const flexEnd = /justify-content\s*:\s*(?:flex-end|right|end)\b/i.test(css);
  const hasGrid = /grid-template-columns/i.test(css);
  if (layoutFamilies.includes(family) && flexEnd && !hasGrid) {
    issues.push("结构型模块（快捷入口/交易账号/开通进度/钱包）把内容靠右/靠边对齐又不用网格，会在主轴留下大块空白；这类模块必须等分铺满整行或用等宽网格列。");
  }
  if (/flex-grow\s*:\s*1\b/i.test(css) && flexEnd && !hasGrid) {
    issues.push("组件用 flex-grow 撑开容器后又把内容靠边对齐，主轴中段会出现大块空白；应铺满容器或改用等分网格列。");
  }
  // 固定大像素宽度无法自适应首页栅格（width 前必须是 ; { 或空白，借此排除 max-width/min-width/border-width）。
  if (/[;{\s]width\s*:\s*(?:[5-9]\d{2}|\d{4,})px/i.test(css)) {
    issues.push("组件使用固定大像素宽度（≥500px），无法自适应首页栅格容器，会溢出或撑出横向空白；宽度应用百分比或自适应布局。");
  }
  if (/首页目标|当前步骤|slot：|模块名称：|Client Home Atom|data-ai-edit-note|AI\s*修改/i.test(source)) {
    issues.push("组件 UI 泄露了管理员提示词或 AI 编辑痕迹。");
  }
  if (generatedComponentVisibleText(component).length < 18 && !/<svg\b|data-home-echart|data-chart/i.test(source)) {
    issues.push("组件可见业务内容过少，容易退化成空壳。");
  }
  return [...new Set(issues)].slice(0, 6);
}

function strictWelcomePromptText(payload = {}) {
  return [
    payload.prompt,
    payload.instruction,
    payload.adjustmentPrompt,
    payload.originalSlotPrompt,
    payload.slotPromptContract?.originalSlotPrompt,
    payload.slotPromptContract?.userPrompt,
    payload.slotContract?.objective,
    payload.context?.prompt,
    payload.currentComponentSummary?.description,
    payload.currentComponentSummary?.sourcePrompt,
  ]
    .filter(Boolean)
    .join(" ");
}

function promptRequestsStrictWelcomeHeader(payload = {}) {
  if (oneOfComponentFamily(payload.family, "") !== "WelcomeHeader") return false;
  const text = strictWelcomePromptText(payload);
  const hasWelcomeCue = /姓名|客户姓名|用户名|昵称|问候|欢迎|最近登录|上次登录|last\s*login|login\s*time/i.test(text);
  const hasLimitCue = /只要求|只需要|只放|只展示|只显示|只保留|仅|只要|不要.{0,24}(营销|开户|入金|资产|KYC|认证|引导|钱包|总资产)/i.test(text);
  return hasWelcomeCue && (hasLimitCue || /最近登录|上次登录|last\s*login|login\s*time/i.test(text));
}

function componentScoreKeyForId(componentId) {
  const id = cleanText(componentId, "", 90);
  return id ? `component:${id}` : "";
}

function componentIdFromScoreKey(scoreKey) {
  const key = cleanText(scoreKey, "", 240);
  return key.startsWith("component:") ? cleanText(key.slice("component:".length), "", 90) : "";
}

function normalizeComponentScoreKey(value) {
  return cleanText(value, "", 240);
}

function readComponentScoreStore() {
  const data = readJsonFile(COMPONENT_SCORE_FILE, { scores: {} });
  const rawScores = data && typeof data.scores === "object" && !Array.isArray(data.scores) ? data.scores : {};
  const scores = {};
  Object.entries(rawScores).forEach(([key, value]) => {
    const scoreKey = normalizeComponentScoreKey(key);
    if (!scoreKey) return;
    scores[scoreKey] = normalizeComponentScore(value, 5);
  });
  return {
    version: 1,
    updatedAt: cleanText(data.updatedAt, "", 40),
    scores,
  };
}

function writeComponentScoreStore(scores = {}) {
  const normalizedScores = {};
  Object.entries(scores).forEach(([key, value]) => {
    const scoreKey = normalizeComponentScoreKey(key);
    if (!scoreKey) return;
    normalizedScores[scoreKey] = normalizeComponentScore(value, 5);
  });
  writeJsonFile(COMPONENT_SCORE_FILE, {
    version: 1,
    updatedAt: new Date().toISOString(),
    scores: Object.fromEntries(Object.entries(normalizedScores).sort(([a], [b]) => a.localeCompare(b))),
  });
  return normalizedScores;
}

function saveComponentScoreEntry(scoreKey, score) {
  const key = normalizeComponentScoreKey(scoreKey);
  if (!key) return readComponentScoreStore().scores;
  const store = readComponentScoreStore();
  store.scores[key] = normalizeComponentScore(score, 5);
  return writeComponentScoreStore(store.scores);
}

function deleteComponentScoreEntries(scoreKeys = []) {
  const keys = new Set((Array.isArray(scoreKeys) ? scoreKeys : [scoreKeys]).map(normalizeComponentScoreKey).filter(Boolean));
  if (!keys.size) return readComponentScoreStore().scores;
  const store = readComponentScoreStore();
  keys.forEach((key) => delete store.scores[key]);
  return writeComponentScoreStore(store.scores);
}

function readComponentLibrary() {
  const data = readJsonFile(COMPONENT_LIBRARY_FILE, { components: [] });
  const scoreStore = readComponentScoreStore().scores;
  const components = Array.isArray(data.components)
    ? data.components
        .map((item) => {
          const normalized = normalizeGeneratedComponent(item, {}, { preserveUpdatedAt: true });
          const storedScore = scoreStore[componentScoreKeyForId(normalized.id)] ?? scoreStore[normalized.id];
          return storedScore == null ? normalized : { ...normalized, score: normalizeComponentScore(storedScore, normalized.score) };
        })
        .filter((item) => item.html && item.css && !generatedComponentTooGeneric(item) && !generatedComponentViolatesFamily(item, { family: item.family }))
    : [];
  return { components };
}

function readRawComponentLibrary() {
  const data = readJsonFile(COMPONENT_LIBRARY_FILE, { components: [] });
  return {
    components: Array.isArray(data.components) ? data.components.filter((component) => component && typeof component === "object") : [],
  };
}

function componentStyleSignals(css) {
  const source = String(css || "");
  const signals = [];
  const add = (condition, label) => {
    if (condition && !signals.includes(label)) signals.push(label);
  };

  add(/display\s*:\s*grid/i.test(source), "grid layout");
  add(/display\s*:\s*flex/i.test(source), "flex alignment");
  add(/grid-template-columns\s*:\s*repeat\(\s*2/i.test(source), "two-column metrics");
  add(/grid-template-columns\s*:\s*repeat\(\s*3/i.test(source), "three-column metrics");
  add(/grid-template-columns\s*:\s*repeat\(\s*[4-6]/i.test(source), "dense action grid");
  add(/border-radius\s*:\s*(?:[0-8](?:\.\d+)?px|0)/i.test(source), "radius <= 8px");
  add(/#eff6ff|#f8fbff|#dbeafe|#bfdbfe|rgba\(37,\s*99,\s*235/i.test(source), "light blue finance");
  add(/#0f172a|#111827|#172033|#020617/i.test(source), "dark finance");
  add(/button|\.primary/i.test(source), "action buttons");
  add(/@media/i.test(source), "responsive rules");

  return signals.slice(0, 8);
}

function summarizeComponentForPrompt(component) {
  const admission = componentReferenceAdmission(component);
  return {
    id: component.id,
    name: component.name,
    family: component.family,
    size: component.size,
    score: admission.score,
    referenceTier: admission.tier,
    referenceRule: admission.rule,
    description: component.description,
    tags: Array.isArray(component.tags) ? component.tags.slice(0, 6) : [],
    layoutHints: Array.isArray(component.layoutHints) ? component.layoutHints.slice(0, 4) : [],
    dataRequirements: Array.isArray(component.dataRequirements) ? component.dataRequirements.slice(0, 6) : [],
    visibleText: stripHtmlTags(component.html).slice(0, 260),
    styleSignals: componentStyleSignals(component.css),
  };
}

function componentStructureSignals(component = {}) {
  const html = String(component.html || "");
  const css = String(component.css || "");
  const combined = `${html}\n${css}`;
  const signals = [];
  const add = (condition, label) => {
    if (condition && !signals.includes(label)) signals.push(label);
  };

  add(/<table\b|<thead\b|<tbody\b/i.test(html), "表格/列表字段密度");
  add(/svg|path/i.test(html), "图标或图形表达");
  add(/chart|curve|sparkline|area|trend|echart|净值|PnL|收益率|曲线/i.test(combined), "趋势/图表证据");
  add(/step|timeline|journey|mission|progress|KYC|开户|入金/i.test(combined), "步骤/状态路径");
  add(/button|data-home-action|cta|primary/i.test(combined), "明确按钮层级");
  add(/badge|tag|status|pill|已|待|进行中|Live|Demo/i.test(combined), "状态标签");
  add(/grid-template-columns\s*:\s*repeat\(\s*3/i.test(css), "三列指标/入口结构");
  add(/grid-template-columns\s*:\s*repeat\(\s*[4-8]/i.test(css), "高密度入口矩阵");
  add(/@media/i.test(css), "响应式降级");

  return signals.slice(0, 8);
}

function componentReferenceFamilySearchText(component = {}) {
  return normalizeKeywordText(
    [
      component.id,
      component.name,
      component.family,
      component.description,
      component.html,
      ...(Array.isArray(component.tags) ? component.tags : []),
      ...(Array.isArray(component.layoutHints) ? component.layoutHints : []),
      ...(Array.isArray(component.dataRequirements) ? component.dataRequirements : []),
    ].join(" "),
  );
}

function componentMatchesReferenceFamily(component = {}, family = "") {
  const requestedFamily = canonicalComponentFamily(family);
  const componentFamily = canonicalComponentFamily(component.family);
  if (!requestedFamily) return true;
  if (componentFamily === requestedFamily) return true;
  const text = componentReferenceFamilySearchText(component);
  if (requestedFamily === "CopytradingSignals") {
    return componentFamily === "ClientHomeAtoms" && /copytrading|copy trading|信号源|signals?|跟单/i.test(text);
  }
  if (requestedFamily === "PammProducts") {
    return componentFamily === "ClientHomeAtoms" && /pamm|资管|产品推荐|策略产品|managed|portfolio/i.test(text);
  }
  if (requestedFamily === "AppDownload") {
    return componentFamily === "ClientHomeAtoms" && /app|下载|二维码|download|mobile/i.test(text);
  }
  return false;
}

function compactComponentReferenceForPrompt(component = {}, options = {}) {
  const summary = summarizeComponentForPrompt(component);
  return {
    ...summary,
    htmlClassHints: [...new Set((String(component.html || "").match(/class=(["'])(.*?)\1/gi) || [])
      .flatMap((item) => item.replace(/^class=(["'])|["']$/g, "").split(/\s+/))
      .filter(Boolean))]
      .slice(0, 8),
    structureSignals: componentStructureSignals(component),
    mustInherit: [
      "业务字段密度",
      "按钮层级",
      "状态标签",
      "卡片比例",
      ...(componentStructureSignals(component).includes("趋势/图表证据") ? ["趋势/图表表达"] : []),
      ...(componentStructureSignals(component).includes("步骤/状态路径") ? ["步骤路径表达"] : []),
    ].filter((item, index, list) => list.indexOf(item) === index).slice(0, 8),
    htmlContract: {
      module: cleanText(options.module || "", "", 80),
      requiredAttribute: `data-component-reference="${cleanText(component.id, "", 96)}"`,
      rule: "对应 data-ai-html-module 区域必须带 data-component-reference，且至少继承两个 mustInherit 维度；不能只把组件 ID 写进 componentReferences。",
    },
  };
}

function seedHomepageConfigFromPrompt(payload = {}) {
  const prompt = String(payload.prompt || "");
  const guidedIntake = guidedAiIntakeFromPayload(payload);
  const intentProfile = applyGuidedIntentProfile(buildHomepageIntentProfile(prompt), guidedIntake);
  const mustHave = Array.isArray(intentProfile.mustHave) && intentProfile.mustHave.length
    ? intentProfile.mustHave
    : AI_HTML_REQUIRED_FALLBACK_BLOCKS;
  return {
    pageIntent: intentProfile,
    heroFocus: intentProfile.heroFocus,
    sections: mustHave.slice(0, 8).map((slot, index) => ({
      id: `local-intent-${index + 1}`,
      type: index === 0 ? "hero" : "full",
      slots: [canonicalHomeBlock(slot) || slot],
    })),
  };
}

function homepageLocalPromptBrickContext(payload = {}, config = {}, options = {}) {
  const prompt = cleanText(payload.prompt, "", 1200);
  const seedConfig = config && Object.keys(config).length ? config : seedHomepageConfigFromPrompt(payload);
  const requiredModules = aiHtmlRequiredModuleContracts(payload, seedConfig);
  const blockCandidates = [
    ...requiredModules.map((item) => item.component),
    ...collectHomepageBlocks(seedConfig),
    ...(Array.isArray(seedConfig.brickPlan) ? seedConfig.brickPlan.flatMap((item) => [item.component, item.feature]) : []),
  ]
    .map(canonicalHomeBlock)
    .filter(Boolean);
  const blocks = [...new Set(blockCandidates)].slice(0, 16);
  const usedIds = new Set();
  const matchedBricks = blocks
    .map((block) => {
      const selected = selectHighScoreBrickForHomepageBlock(block, payload, seedConfig, usedIds);
      if (!selected) return null;
      const moduleContract = requiredModules.find((item) => item.component === block) || AI_HTML_MODULE_CONTRACTS[block] || {};
      const brick = homepageBrickPlanItemForBlock(seedConfig, block);
      return {
        module: block,
        label: moduleContract.label || block,
        requiredFamily: selected.requestedFamily,
        requestedSize: selected.requestedSize,
        sourceBrickId: cleanText(brick?.brickId, "", 96),
        sourceBrickName: cleanText(brick?.brickName, "", 96),
        sourceBrickReason: cleanText(brick?.reason || brick?.brickReason, "", 180),
        reference: compactComponentReferenceForPrompt(selected.component, { module: block }),
      };
    })
    .filter(Boolean)
    .slice(0, Number(options.limit) || 10);

  const primaryCta = expectedPrimaryCtaForPrompt(prompt, seedConfig);
  return {
    processingPipeline: "local-prompt-understanding -> canonical-block-map -> high-score-brick-hit -> model-reference-pack -> post-generation-conformance-gate",
    promptUnderstanding: {
      primaryIntent: seedConfig.pageIntent?.primaryIntent || homepageIntentFromPrompt(prompt),
      heroFocus: cleanText(seedConfig.heroFocus || seedConfig.pageIntent?.heroFocus, "", 80),
      primaryCta: primaryCta ? { label: primaryCta.label, action: primaryCta.action } : null,
      requiredBlocks: blocks,
      forbiddenCarryOver: [
        "不能直接把用户 prompt 发给模型自由发挥",
        "不能只在 componentReferences 写 ID 而 HTML 仍是普通白卡",
        "不能使用 5 分及以下积木作为参考或兜底",
      ],
    },
    matchedBricks,
    modelHardRules: [
      "生成前必须先按 matchedBricks 决定模块结构，模型只做同款微调或可解释升级。",
      "每个命中积木的 data-ai-html-module 区域必须写 data-component-reference=componentId。",
      "HTML 必须继承 reference.mustInherit 中至少两个维度，例如字段密度、按钮层级、状态标签、图表/列表/步骤表达。",
      "componentReferences 只是追踪记录，不能替代 HTML 里的真实结构表达。",
      "如果无法证明比高分积木更好，直接回到高分积木同款微调。",
    ],
  };
}

function rankComponentReferences(components, options = {}) {
  const family = cleanText(options.family, "", 60);
  const size = cleanText(options.size, "", 12);
  const prompt = normalizeKeywordText(options.prompt || "");
  const limit = Math.max(1, Math.min(Number(options.limit) || 8, 16));
  const includeBlocked = Boolean(options.includeBlockedReferences);

  return components
    .map((component, index) => {
      const admission = componentReferenceAdmission(component, options);
      const haystack = normalizeKeywordText(
        [
          component.id,
          component.name,
          component.family,
          component.size,
          component.description,
          ...(Array.isArray(component.tags) ? component.tags : []),
          ...(Array.isArray(component.dataRequirements) ? component.dataRequirements : []),
        ].join(" "),
      );
      const promptHits = prompt
        ? prompt
            .split(/\s+|[，,。；;、]/)
            .filter((word) => word.length >= 2 && haystack.includes(word))
            .length
        : 0;

      // 升级 #4：尺寸适配改为分级——完全吻合加分，差得越远扣得越多，避免把窄积木硬塞进宽槽位（或反之）。
      const fitDistance = size ? componentSizeDistance(component.size, size) : 0;
      return {
        component,
        admission,
        score:
          componentReferenceTierPriority(admission.tier) +
          admission.score * 18 +
          (family && component.family === family ? 80 : 0) +
          (size && component.size === size ? 28 : 0) -
          fitDistance * 9 +
          promptHits * 8 +
          Math.max(0, 20 - Math.min(index, 20)) * 0.2,
      };
    })
    .filter((item) => includeBlocked || item.admission.allowed)
    .sort((a, b) => b.score - a.score || b.admission.score - a.admission.score)
    .map((item) => item.component)
    .slice(0, limit);
}

function componentSizeColumns(size) {
  const match = normalizeComponentSize(size, "2x1").match(/^([1-9]\d?)x/);
  return match ? Number(match[1]) || 2 : 2;
}

function componentSizeDistance(firstSize, secondSize) {
  return (
    Math.abs(componentSizeColumns(firstSize) - componentSizeColumns(secondSize)) +
    Math.abs(componentSizeRows(firstSize) - componentSizeRows(secondSize))
  );
}

function componentFallbackExcludeIds(payload = {}, options = {}) {
  return [
    options.excludeIds,
    payload.excludeIds,
    payload.excludeComponentIds,
    payload.avoidComponentIds,
    payload.currentComponentId,
    payload.componentId,
    payload.currentComponentSummary?.id,
    payload.currentComponentSummary?.referenceComponentId,
    payload.currentComponent?.id,
    payload.component?.id,
    payload.component?.referenceComponentId,
  ]
    .flat(Infinity)
    .map((id) => cleanText(id, "", 90))
    .filter(Boolean);
}

function componentLibraryFallbackForPayload(payload = {}, options = {}) {
  const family = oneOfComponentFamily(payload.family);
  const size = normalizeComponentSize(payload.size, autoComponentSizeForPayload(payload, family));
  if (promptRequestsStrictWelcomeHeader({ ...payload, family })) return null;
  const prompt = cleanText(payload.prompt || payload.instruction || "", "", 500);
  const excludeIds = new Set(componentFallbackExcludeIds(payload, options));
  const libraryComponents = readComponentLibrary().components.filter((component) => !excludeIds.has(component.id) && componentReferenceAllowed(component, payload));
  if (!libraryComponents.length) return null;

  const compatibleFamily = libraryComponents.filter((component) => componentMatchesReferenceFamily(component, family));
  const pool = family === "ClientHomeAtoms" ? libraryComponents.filter((component) => component.family === "ClientHomeAtoms") : compatibleFamily;
  if (!pool.length) return null;

  const ranked = rankComponentReferences(pool, {
    family,
    size,
    prompt,
    limit: 16,
  });
  const selected =
    ranked.find((component) => component.family === family && component.size === size) ||
    ranked
      .filter((component) => component.family === family)
      .sort((a, b) => componentSizeDistance(a.size, size) - componentSizeDistance(b.size, size))[0] ||
    ranked[0];
  if (!selected) return null;

  const reason = cleanText(options.reason, "模型组件生成失败，已引用组件库积木兜底。", 260);
  const layoutContract = normalizeComponentGridContract(selected.layoutContract || payload.layoutContext, size, {
    zone: payload.slotContract?.sectionType,
    slot: payload.slotContract?.id,
    sectionType: payload.slotContract?.sectionType,
  });
  return {
    ...selected,
    sourceType: "brick-fallback",
    fallbackReason: reason,
    fallbackMode: "high-score-same-brick-micro-tune",
    fallbackContract: "高分积木同款保底：保留原组件 HTML/CSS 主结构，只允许主题 token、响应式、动作绑定、文案和尺寸适配的微调。",
    referenceComponentId: selected.id,
    referenceComponentName: selected.name,
    referenceFamily: selected.family,
    referenceScore: componentReferenceScore(selected, payload),
    referenceTier: componentReferenceTierFromScore(componentReferenceScore(selected, payload)),
    requestedFamily: family,
    requestedSize: size,
    requestedSpan: layoutContract.desktopSpan,
    layoutContract,
    generatedAt: new Date().toISOString(),
    layoutHints: [
      ...(Array.isArray(selected.layoutHints) ? selected.layoutHints : []),
      `fallback:${family}`,
      `requested-size:${size}`,
    ].filter(Boolean).slice(0, 8),
  };
}

function componentLibraryPromptReference(options = {}) {
  const family = cleanText(options.family, "", 60);
  const components = readComponentLibrary().components.filter((component) => componentMatchesReferenceFamily(component, family));
  const selected = rankComponentReferences(components, options);
  const policy = componentReferencePolicyPrompt(components, options);

  return {
    referenceMode: "先用 5 分以上可参考积木锁定业务字段、尺寸、按钮、标签、卡片密度和视觉层级；保底同款微调，推荐在积木基础上做更好的页面规划和排版升级。",
    scoringRule: "score 为用户 1-10 分评分；8-10 分强参考，6-7 分适度参考，5 分及以下禁止参考。",
    constraintPolicy: componentReferenceConstraintPolicy(),
    referencePolicy: policy,
    freedomRule: "允许有 AI 灵感，但灵感必须依托现有父模块、真实字段、可用尺寸或组件语言；不能把组件库参考当成新增业务能力授权。",
    availableCount: components.length,
    referenceableCount: policy.counts.referenceable,
    selectedComponents: selected.map(summarizeComponentForPrompt),
  };
}

