function homepageComponentReferenceText(component) {
  return normalizeKeywordText(
    [
      component?.id,
      component?.name,
      component?.family,
      component?.size,
      component?.description,
      ...(Array.isArray(component?.tags) ? component.tags : []),
      ...(Array.isArray(component?.layoutHints) ? component.layoutHints : []),
      ...(Array.isArray(component?.dataRequirements) ? component.dataRequirements : []),
      stripHtmlTags(component?.html || "").slice(0, 500),
    ].join(" "),
  );
}

function inferHomepageComponentReferenceHints(moduleId, component) {
  const text = homepageComponentReferenceText(component);
  const rule = (HOMEPAGE_COMPONENT_REFERENCE_RULES[moduleId] || []).find((item) =>
    item.keys.some((key) => text.includes(normalizeKeywordText(key))),
  );
  return {
    variant: rule?.variant || "",
    morph: rule?.morph || "",
    style: rule?.style || "",
    styleFeature: (HOMEPAGE_COMPONENT_REFERENCE_STYLE_FEATURES[moduleId] || [])[0] || "",
  };
}

function homepageComponentReferenceForBlock(block) {
  const canonical = canonicalHomeBlock(block);
  if (!canonical) return "";
  return HOMEPAGE_COMPONENT_REFERENCE_MODULE_MAP[canonical] || "";
}

function normalizeHomepageConfigComponentReferences(value) {
  return (Array.isArray(value) ? value : [])
    .map((item) =>
      enrichComponentReferencePolicy({
        componentId: cleanText(item?.componentId || item?.id, "", 96),
        id: cleanText(item?.id || item?.componentId, "", 96),
        name: cleanText(item?.name, "", 80),
        family: cleanText(item?.family, "", 80),
        module: cleanText(item?.module || item?.moduleId, "", 80),
        component: canonicalHomeBlock(item?.component || item?.feature) || cleanText(item?.component || item?.feature, "", 80),
        size: cleanText(item?.size, "", 16),
        score: Number.isFinite(Number(item?.score)) ? normalizeComponentScore(item.score, COMPONENT_REFERENCE_SCORE_POLICY.blockedMax) : undefined,
        tags: (Array.isArray(item?.tags) ? item.tags : []).map((tag) => cleanText(tag, "", 32)).filter(Boolean).slice(0, 8),
        layoutHints: (Array.isArray(item?.layoutHints) ? item.layoutHints : []).map((hint) => cleanText(hint, "", 120)).filter(Boolean).slice(0, 6),
        styleSignals: (Array.isArray(item?.styleSignals) ? item.styleSignals : []).map((signal) => cleanText(signal, "", 80)).filter(Boolean).slice(0, 8),
        visibleText: cleanText(item?.visibleText, "", 260),
        variantHint: cleanText(item?.variantHint || item?.variant, "", 48),
        morphHint: cleanText(item?.morphHint || item?.morph || item?.morphId, "", 48),
        styleHint: cleanText(item?.styleHint || item?.style, "", 48),
        styleFeature: cleanText(item?.styleFeature, "", 48),
        rendererMode: cleanText(item?.rendererMode, "", 40),
        rendererHtml: sanitizeAiHtmlMarkup(item?.rendererHtml || item?.html || ""),
        rendererCss: enforceGoldenThemeOnCss(sanitizeAiHtmlCss(item?.rendererCss || item?.css || "")),
        rendererQualityFloor: Number.isFinite(Number(item?.rendererQualityFloor))
          ? Math.max(1, Math.min(10, Math.round(Number(item.rendererQualityFloor))))
          : undefined,
        reason: cleanText(item?.reason, "", 180),
        source: cleanText(item?.source, "home-component-library", 48),
        applied: Boolean(item?.applied),
      })
    )
    .filter((item) => item.componentId && item.name && item.family)
    .slice(0, 12);
}

function blockedComponentReferenceIdSet(components = readComponentLibrary().components) {
  return new Set(
    (Array.isArray(components) ? components : [])
      .filter((component) => !componentReferenceAllowed(component))
      .map((component) => component.id)
      .filter(Boolean),
  );
}

function rawBlockedComponentReferenceIdSet() {
  return new Set(
    (readRawComponentLibrary().components || [])
      .filter((component) => componentReferenceTierFromScore(component?.score) === "blocked")
      .map((component) => cleanText(component?.id, "", 96))
      .filter(Boolean),
  );
}

function stripBlockedComponentReferenceFields(value = {}) {
  const next = { ...value };
  [
    "referenceComponentId",
    "referenceComponentName",
    "referenceFamily",
    "referenceScore",
    "referenceTier",
    "referenceRule",
    "referenceReason",
    "componentReferenceId",
    "componentReferenceName",
    "rendererMode",
    "rendererHtml",
    "rendererCss",
    "rendererQualityFloor",
  ].forEach((key) => {
    delete next[key];
  });
  return next;
}

function purgeBlockedComponentReferencesFromConfig(config, options = {}) {
  if (!config || typeof config !== "object") return config;
  const components = readComponentLibrary().components;
  const lookup = componentLibraryLookup(components);
  const blockedIds = blockedComponentReferenceIdSet(components);
  const rawBlockedIds = rawBlockedComponentReferenceIdSet();
  const removed = new Set();
  const isBlockedReference = (reference = {}) => {
    const id = cleanText(reference.componentId || reference.id || reference.referenceComponentId || reference.componentReferenceId, "", 96);
    const blocked = (id && (blockedIds.has(id) || rawBlockedIds.has(id))) || !componentReferenceAllowedByPolicy(reference, lookup);
    if (blocked && id) removed.add(id);
    return blocked;
  };

  const componentReferences = normalizeHomepageConfigComponentReferences(config.componentReferences);
  config.componentReferences = componentReferences.filter((reference) => !isBlockedReference(reference));

  if (config.componentMorphs && typeof config.componentMorphs === "object") {
    config.componentMorphs = Object.fromEntries(
      Object.entries(config.componentMorphs).map(([moduleId, morph]) => {
        if (!morph || typeof morph !== "object" || !isBlockedReference(morph)) return [moduleId, morph];
        return [moduleId, stripBlockedComponentReferenceFields(morph)];
      }),
    );
  }

  if (Array.isArray(config.brickPlan)) {
    config.brickPlan = config.brickPlan.map((brick) => {
      if (!brick || typeof brick !== "object" || !isBlockedReference(brick)) return brick;
      return stripBlockedComponentReferenceFields(brick);
    });
  }

  if (config.htmlScheme && typeof config.htmlScheme === "object" && Array.isArray(config.htmlScheme.componentReferences)) {
    config.htmlScheme = {
      ...config.htmlScheme,
      componentReferences: normalizeAiHtmlComponentReferences(config.htmlScheme.componentReferences).filter((reference) => !isBlockedReference(reference)),
    };
  }

  if (config.skeletonHtmlScheme && typeof config.skeletonHtmlScheme === "object" && config.skeletonHtmlScheme.slotComponents && typeof config.skeletonHtmlScheme.slotComponents === "object") {
    const slotComponents = { ...config.skeletonHtmlScheme.slotComponents };
    Object.entries(slotComponents).forEach(([slotId, component]) => {
      if (!component || typeof component !== "object") return;
      const reference = {
        id: component.id,
        componentId: component.referenceComponentId || component.id,
        score: component.score,
        referenceTier: component.referenceTier,
      };
      if (isBlockedReference(reference)) {
        delete slotComponents[slotId];
        return;
      }
      // 骨架槽位积木的 CSS 也要服从黄金主题，否则自带青绿/异色的积木装进骨架后整页变拼盘。
      const nested = component.component && typeof component.component === "object" ? component.component : null;
      if (typeof component.css === "string" && component.css) {
        slotComponents[slotId] = { ...component, css: enforceGoldenThemeOnCss(component.css) };
      }
      if (nested && typeof nested.css === "string" && nested.css) {
        const target = slotComponents[slotId];
        slotComponents[slotId] = { ...target, component: { ...nested, css: enforceGoldenThemeOnCss(nested.css) } };
      }
    });
    config.skeletonHtmlScheme = { ...config.skeletonHtmlScheme, slotComponents };
  }

  if (removed.size && Array.isArray(options.actions)) {
    options.actions.push(`已直接杜绝 ${removed.size} 个 5 分及以下组件引用：${[...removed].slice(0, 6).join(", ")}。`);
  }
  return config;
}

function shouldApplyHomepageReferenceVariant(config, moduleId, variantHint) {
  if (!variantHint) return false;
  const existingVariant = moduleVariantFromConfig(config, moduleId);
  const defaultVariant = HOMEPAGE_COMPONENT_REFERENCE_DEFAULT_VARIANTS[moduleId] || "";
  return !existingVariant || existingVariant === variantHint || existingVariant === defaultVariant || existingVariant === "standard";
}

function applyComponentReferencesToHomepageConfig(config, prompt = "", options = {}) {
  if (!config || typeof config !== "object") return [];
  const allComponents = readComponentLibrary().components;
  const componentLookup = componentLibraryLookup(allComponents);
  const rawBlockedIds = rawBlockedComponentReferenceIdSet();
  const components = allComponents.filter((component) => componentReferenceAllowed(component) && !rawBlockedIds.has(component.id));
  if (!components.length) {
    const existing = normalizeHomepageConfigComponentReferences(config.componentReferences)
      .filter((reference) => !rawBlockedIds.has(reference.componentId || reference.id) && componentReferenceAllowedByPolicy(reference, componentLookup));
    config.componentReferences = existing;
    return config.componentReferences;
  }

  const blocks = collectHomepageBlocks(config);
  const moduleBlocks = [];
  const seenModules = new Set();
  blocks.forEach((block) => {
    const moduleId = homepageComponentReferenceForBlock(block);
    if (!moduleId || seenModules.has(moduleId)) return;
    seenModules.add(moduleId);
    moduleBlocks.push({ block, moduleId });
  });

  const usedComponentIds = new Set();
  const references = moduleBlocks
    .map(({ block, moduleId }) => {
      const familyComponents = components.filter((component) => component.family === moduleId);
      if (!familyComponents.length) return null;
      const ranked = rankComponentReferences(familyComponents, {
        prompt,
        family: moduleId,
        size: homepageBlockMeta(block).size || "",
        limit: Math.min(familyComponents.length, 6),
      });
      const selected =
        ranked.find((component) => !usedComponentIds.has(component.id) && componentReferenceAdmission(component).tier === "strong") ||
        ranked.find((component) => !usedComponentIds.has(component.id)) ||
        familyComponents[0];
      if (!selected) return null;
      usedComponentIds.add(selected.id);
      const summary = summarizeComponentForPrompt(selected);
      const hints = inferHomepageComponentReferenceHints(moduleId, selected);
      const strongRenderer = summary.referenceTier === "strong";
      return {
        componentId: summary.id,
        id: summary.id,
        name: summary.name,
        family: summary.family,
        module: moduleId,
        component: block,
        size: summary.size,
        score: summary.score,
        referenceTier: summary.referenceTier,
        referenceRule: summary.referenceRule,
        tags: summary.tags,
        layoutHints: summary.layoutHints,
        styleSignals: summary.styleSignals,
        visibleText: summary.visibleText,
        variantHint: hints.variant,
        morphHint: hints.morph,
        styleHint: hints.style,
        styleFeature: hints.styleFeature,
        rendererMode: strongRenderer ? "high-score-component" : "",
        rendererHtml: strongRenderer ? sanitizeAiHtmlMarkup(selected.html) : "",
        rendererCss: strongRenderer ? enforceGoldenThemeOnCss(sanitizeAiHtmlCss(selected.css)) : "",
        rendererQualityFloor: strongRenderer ? COMPONENT_REFERENCE_SCORE_POLICY.strongMin : undefined,
        source: "home-component-library",
        reason: cleanText(`参考「${summary.name}」的字段密度、比例和 ${hints.morph || hints.variant || "组件结构"}，并映射到 ${block}。`, "", 180),
        applied: false,
      };
    })
    .filter(Boolean);

  const existingReferences = normalizeHomepageConfigComponentReferences(config.componentReferences)
    .filter((item) => !rawBlockedIds.has(item.componentId || item.id) && componentReferenceAllowedByPolicy(item, componentLookup))
    .filter((item) => !references.some((reference) => reference.componentId === item.componentId || (reference.module && reference.module === item.module)))
    .slice(0, Math.max(0, 12 - references.length));
  const blockedExistingCount = normalizeHomepageConfigComponentReferences(config.componentReferences)
    .filter((item) => rawBlockedIds.has(item.componentId || item.id) || !componentReferenceAllowedByPolicy(item, componentLookup))
    .length;
  const mergedReferences = normalizeHomepageConfigComponentReferences([...references, ...existingReferences]);
  if (blockedExistingCount && Array.isArray(options.actions)) {
    options.actions.push(`已剔除 ${blockedExistingCount} 个 5 分及以下组件库参考，避免低分积木参与生成。`);
  }

  config.modules = ensureObject(config.modules);
  config.moduleStyles = ensureObject(config.moduleStyles);
  config.componentMorphs = ensureObject(config.componentMorphs);

  const appliedModules = [];
  mergedReferences.forEach((reference) => {
    const moduleId = reference.module;
    if (!moduleId) return;
    const canApplyVariant = shouldApplyHomepageReferenceVariant(config, moduleId, reference.variantHint);
    if (canApplyVariant) {
      config.modules[moduleId] = { ...ensureObject(config.modules[moduleId]), variant: reference.variantHint };
      reference.applied = true;
      appliedModules.push(moduleId);
    }
    const existingVariant = moduleVariantFromConfig(config, moduleId);
    const defaultVariant = HOMEPAGE_COMPONENT_REFERENCE_DEFAULT_VARIANTS[moduleId] || "";
    const canApplyStyle =
      reference.styleHint &&
      (canApplyVariant || !existingVariant || existingVariant === reference.variantHint || existingVariant === defaultVariant || existingVariant === "standard");
    if (canApplyStyle) {
      (HOMEPAGE_COMPONENT_REFERENCE_STYLE_FEATURES[moduleId] || [reference.styleFeature]).filter(Boolean).forEach((featureId, index) => {
        if (index === 0 || !config.moduleStyles[featureId]) config.moduleStyles[featureId] = reference.styleHint;
      });
      reference.applied = true;
    }
    const existingMorph = ensureObject(config.componentMorphs[moduleId]);
    const variant = config.modules[moduleId]?.variant || reference.variantHint || existingMorph.variant || "";
    config.componentMorphs[moduleId] = {
      ...existingMorph,
      ...(canApplyVariant && reference.morphHint ? { morph: reference.morphHint, morphId: reference.morphHint } : {}),
      variant,
      referenceComponentId: reference.componentId,
      referenceComponentName: reference.name,
      referenceFamily: reference.family,
      referenceScore: reference.score,
      referenceTier: reference.referenceTier,
      referenceReason: reference.reason,
    };
  });

  config.componentReferences = mergedReferences;
  const rendererReferences = mergedReferences.filter(
    (reference) =>
      reference.referenceTier === "strong" &&
      Number(reference.score) >= COMPONENT_REFERENCE_SCORE_POLICY.strongMin &&
      reference.rendererHtml &&
      reference.rendererCss,
  );
  const strongRendererModules = new Set(rendererReferences.map((reference) => reference.module).filter(Boolean));
  // moderate(≥6) 兜底渲染：某些模块(如 copytrading_signals/risk_disclosure/pamm_products)在整个组件库里没有任何
  // ≥8 强组件可用 → 之前只能走通用占位，导致"走样/不跟随设计风格"。这里允许这些"无强组件"模块用其最高分的、
  // 带 rendererHtml/Css 的 ≥6 同模块组件兜底渲染（标记 rendererFallback），至少拿到一个跟随 --home-* token 的设计组件。
  // 注意：这是"次优兜底"，治本仍需为这些 family 产出 ≥8 组件。
  const fallbackRendererReferences = [];
  const fallbackSeen = new Set();
  mergedReferences
    .filter(
      (reference) =>
        reference.module &&
        !strongRendererModules.has(reference.module) &&
        reference.referenceTier !== "blocked" &&
        Number(reference.score) >= COMPONENT_REFERENCE_SCORE_POLICY.moderateMin &&
        reference.rendererHtml &&
        reference.rendererCss,
    )
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .forEach((reference) => {
      if (fallbackSeen.has(reference.module)) return;
      fallbackSeen.add(reference.module);
      reference.rendererFallback = true;
      fallbackRendererReferences.push(reference);
    });
  config.componentRenderPolicy = {
    mode: "strong-reference-snippet-fallback",
    minimumRendererScore: COMPONENT_REFERENCE_SCORE_POLICY.strongMin,
    fallbackRendererMinimumScore: COMPONENT_REFERENCE_SCORE_POLICY.moderateMin,
    fallbackWhenGeneratedScoreBelow: 68,
    appliedModules: rendererReferences.map((reference) => reference.module).filter(Boolean),
    fallbackModules: fallbackRendererReferences.map((reference) => reference.module).filter(Boolean),
    source: "home-component-library",
  };
  if (Array.isArray(config.brickPlan)) {
    config.brickPlan = config.brickPlan.map((brick) => {
      const component = canonicalHomeBlock(brick?.component || brick?.feature);
      const moduleId = homepageComponentReferenceForBlock(component);
      const reference = mergedReferences.find((item) => item.module === moduleId || item.component === component);
      if (!reference) return brick;
      return {
        ...brick,
        referenceComponentId: reference.componentId,
        referenceComponentName: reference.name,
        referenceFamily: reference.family,
        referenceScore: reference.score,
        referenceTier: reference.referenceTier,
        referenceReason: reference.reason,
        variantHint: reference.variantHint || brick.variantHint,
        morphHint: reference.morphHint || brick.morphHint,
        styleHint: reference.styleHint || brick.styleHint,
      };
    });
  }

  if (appliedModules.length && Array.isArray(options.actions)) {
    options.actions.push(`已把组件库积木参考应用到模块变体：${[...new Set(appliedModules)].join(", ")}。`);
  }
  enforceServerComponentMorphs(config);
  purgeBlockedComponentReferencesFromConfig(config, options);
  return config.componentReferences;
}

function scoreContextPromptReference(value) {
  const source = Array.isArray(value) ? value : [];
  return source
    .map((item) => ({
      type: cleanText(item?.type, "", 32),
      family: cleanText(item?.family, "", 80),
      name: cleanText(item?.name, "", 80),
      size: normalizeComponentSize(item?.size, "2x1"),
      score: normalizeComponentScore(item?.score, COMPONENT_REFERENCE_SCORE_POLICY.blockedMax),
      referenceTier: componentReferenceTierFromScore(item?.score),
      visibleText: cleanText(item?.visibleText, "", 260),
      description: cleanText(item?.description, "", 180),
    }))
    .filter((item) => item.name && item.family)
    .filter((item) => item.referenceTier !== "blocked")
    .sort((a, b) => b.score - a.score)
    .slice(0, 8);
}

function savedCompositionPromptReference(limit = 6) {
  const data = readJsonFile(COMPOSITION_LIBRARY_FILE, { compositions: [] });
  const compositions = Array.isArray(data.compositions) ? data.compositions : [];
  return compositions
    .slice(-Math.max(1, Math.min(Number(limit) || 6, 10)))
    .map((composition) => ({
      id: cleanText(composition.id, "", 80),
      name: cleanText(composition.name, "", 80),
      summary: cleanText(composition.summary, "", 220),
      layout: (Array.isArray(composition.layout) ? composition.layout : []).slice(0, 8).map((item) => ({
        componentId: cleanText(item?.componentId, "", 80),
        size: cleanText(item?.size, "", 12),
        zone: cleanText(item?.zone, "", 20),
        reason: cleanText(item?.reason, "", 160),
      })),
      themeAdvice: cleanText(composition.themeAdvice, "", 180),
      polishInstructions: cleanText(composition.polishInstructions, "", 220),
    }));
}

function normalizeDesignFunction(item = {}) {
  return {
    name: cleanText(item.name || item.label, "首页功能", 60),
    objective: cleanText(item.objective || item.goal || item.description, "", 180),
    modules: (Array.isArray(item.modules) ? item.modules : []).map((module) => cleanText(module, "", 80)).filter(Boolean).slice(0, 10),
    data: (Array.isArray(item.data) ? item.data : []).map((field) => cleanText(field, "", 80)).filter(Boolean).slice(0, 10),
    actions: (Array.isArray(item.actions) ? item.actions : []).map((action) => cleanText(action, "", 80)).filter(Boolean).slice(0, 8),
    states: (Array.isArray(item.states) ? item.states : []).map((state) => cleanText(state, "", 80)).filter(Boolean).slice(0, 8),
  };
}

function normalizeSampleBlock(item = {}) {
  return {
    id: safeId(item.id || item.name || item.label, "sample-block"),
    name: cleanText(item.name || item.label, "样本块", 60),
    page: cleanText(item.page || item.pageRole || item.area, "", 80),
    function: cleanText(item.function || item.functionName || item.objective, "", 160),
    componentRefs: (Array.isArray(item.componentRefs) ? item.componentRefs : []).map((id) => cleanText(id, "", 80)).filter(Boolean).slice(0, 8),
    visualNotes: (Array.isArray(item.visualNotes) ? item.visualNotes : []).map((note) => cleanText(note, "", 120)).filter(Boolean).slice(0, 6),
    dataFields: (Array.isArray(item.dataFields) ? item.dataFields : []).map((field) => cleanText(field, "", 80)).filter(Boolean).slice(0, 8),
  };
}

