const GOLDEN_SAMPLE_ANALYSIS_FILE_LIMIT = 6;

function uniqueCleanValues(values = [], limit = 10, textLimit = 120) {
  const seen = new Set();
  const output = [];
  (Array.isArray(values) ? values : []).forEach((value) => {
    const text = cleanText(value, "", textLimit);
    const key = text.toLowerCase();
    if (!text || seen.has(key)) return;
    seen.add(key);
    output.push(text);
  });
  return output.slice(0, limit);
}

function matchCleanValues(source = "", pattern, limit = 12, mapper = (match) => match[1] || match[0], textLimit = 120) {
  const matches = [];
  const regex = new RegExp(pattern.source, pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`);
  for (const match of String(source || "").matchAll(regex)) {
    const value = mapper(match);
    if (Array.isArray(value)) matches.push(...value);
    else matches.push(value);
    if (matches.length >= limit * 2) break;
  }
  return uniqueCleanValues(matches, limit, textLimit);
}

function goldenAnalysisFileType(file = {}) {
  const source = `${file.mime || ""} ${file.name || ""}`.toLowerCase();
  if (/image\/|\.png|\.jpe?g|\.webp|\.gif$/.test(source)) return "image";
  if (/html|\.html?$/.test(source)) return "html";
  if (/css|\.css$/.test(source)) return "css";
  if (/javascript|ecmascript|\.mjs$|\.cjs$|\.js$/.test(source)) return "js";
  if (/pdf|\.pdf$/.test(source)) return "pdf";
  return "file";
}

function normalizeGoldenAnalysisFile(file = {}) {
  const name = cleanText(file.name, "黄金样本文件", 120);
  const mime = cleanText(file.mime, "", 80);
  const type = goldenAnalysisFileType({ ...file, name, mime });
  const rawText = String(file.textContent || "");
  const textContent =
    type === "html"
      ? sanitizeReferenceDocumentHtml(rawText)
      : type === "css"
        ? sanitizeGeneratedCss(rawText)
        : type === "js"
          ? rawText.slice(0, 80_000)
          : rawText.slice(0, 40_000);
  const width = Number(file.width);
  const height = Number(file.height);
  return {
    name,
    mime,
    type,
    size: Number.isFinite(Number(file.size)) ? Math.max(0, Number(file.size)) : 0,
    textContent,
    textExcerpt: cleanText(stripHtmlTags(type === "html" ? contentOnlyReferenceHtml(textContent) : textContent), "", 900),
    width: Number.isFinite(width) ? Math.max(0, Math.round(width)) : 0,
    height: Number.isFinite(height) ? Math.max(0, Math.round(height)) : 0,
    aspectRatio: cleanText(file.aspectRatio, "", 24),
    layoutHint: cleanText(file.layoutHint, "", 140),
    dominantColors: uniqueCleanValues(file.dominantColors || [], 8, 24),
    brightness: cleanText(file.brightness, "", 24),
  };
}

function goldenAnalysisSearchText(files = [], metadata = {}) {
  return [
    metadata.name,
    metadata.prompt,
    metadata.pageIntent,
    metadata.themePreset,
    metadata.visualStyle,
    ...(Array.isArray(metadata.scenarioTags) ? metadata.scenarioTags : []),
    ...files.flatMap((file) => [file.name, file.type, file.textExcerpt, file.layoutHint, file.brightness, ...(file.dominantColors || [])]),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function extractGoldenHtmlStructure(files = []) {
  const html = files.filter((file) => file.type === "html").map((file) => contentOnlyReferenceHtml(file.textContent)).join("\n");
  const htmlText = cleanText(stripHtmlTags(html), "", 1200);
  const tags = ["header", "nav", "main", "section", "article", "aside", "footer"].filter((tag) => new RegExp(`<${tag}\\b`, "i").test(html));
  const headings = matchCleanValues(
    html,
    /<(h[1-4]|strong|summary)\b[^>]*>([\s\S]{1,240}?)<\/\1>/gi,
    14,
    (match) => stripHtmlTags(match[2]),
    90,
  );
  const classNames = matchCleanValues(
    html,
    /\bclass\s*=\s*["']([^"']+)["']/gi,
    28,
    (match) => String(match[1] || "").split(/\s+/),
    60,
  );
  const dataHooks = matchCleanValues(html, /\bdata-[\w-]+\s*=\s*["']?([^"'\s>]+)/gi, 14, (match) => match[1], 80);
  const sectionCount = (html.match(/<(section|article|aside)\b/gi) || []).length;
  return {
    hasHtml: Boolean(html.trim()),
    tags,
    headings,
    classNames,
    dataHooks,
    sectionCount,
    textExcerpt: htmlText,
  };
}

function cssDeclarationValues(css = "", propertyPattern, limit = 10) {
  return matchCleanValues(css, new RegExp(`(?:^|[;{])\\s*(?:${propertyPattern})\\s*:\\s*([^;}]+)`, "gi"), limit, (match) => match[1], 80);
}

function goldenCssTextFromFiles(files = []) {
  const htmlCss = files
    .filter((file) => file.type === "html")
    .flatMap((file) => matchCleanValues(file.textContent, /<style\b[^>]*>([\s\S]*?)<\/style>/gi, 20, (match) => match[1], 5000));
  const inlineStyles = files
    .filter((file) => file.type === "html")
    .flatMap((file) => matchCleanValues(contentOnlyReferenceHtml(file.textContent), /\bstyle\s*=\s*["']([^"']+)["']/gi, 40, (match) => match[1], 500));
  return [
    ...files.filter((file) => file.type === "css").map((file) => file.textContent),
    ...htmlCss,
    ...inlineStyles,
  ].join("\n");
}

function extractGoldenCssVariables(css = {}) {
  const tokens = {};
  for (const match of String(css || "").matchAll(/(--[\w-]+)\s*:\s*([^;}]+)/g)) {
    const key = cleanText(match[1], "", 80);
    const value = cleanText(match[2], "", 160);
    if (!key || !value || Object.keys(tokens).length >= 80) break;
    tokens[key] = value;
  }
  return tokens;
}

function extractGoldenLayoutTokens(css = "", htmlStructure = {}) {
  const gridTemplates = matchCleanValues(css, /grid-template-columns\s*:\s*([^;}]+)/gi, 10, (match) => match[1], 120);
  const maxWidths = cssDeclarationValues(css, "(?:max-)?width", 12).filter((item) => /\d|clamp|minmax|calc|var\(/i.test(item));
  const heights = cssDeclarationValues(css, "(?:min-|max-)?height", 10).filter((item) => /\d|clamp|minmax|calc|var\(/i.test(item));
  const gapScale = cssDeclarationValues(css, "gap|row-gap|column-gap", 12);
  const paddingScale = cssDeclarationValues(css, "padding|padding-inline|padding-block", 12);
  const marginScale = cssDeclarationValues(css, "margin|margin-inline|margin-block", 10);
  const breakpoints = matchCleanValues(css, /@media\s*([^{]+)/gi, 10, (match) => match[1], 120);
  return {
    maxWidths,
    heights,
    gridTemplates,
    gapScale,
    paddingScale,
    marginScale,
    breakpoints,
    sectionCount: htmlStructure.sectionCount || 0,
    hierarchyDepth: htmlStructure.headings?.length || 0,
    hasNavigation: htmlStructure.tags?.includes("nav") || false,
  };
}

function htmlAttributeValue(tag = "", name = "") {
  const escaped = String(name || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const match = new RegExp(`\\b${escaped}\\s*=\\s*["']([^"']+)["']`, "i").exec(tag);
  return cleanText(match?.[1], "", 500);
}

function classifyGoldenComponentCard(className = "", text = "") {
  const source = `${className} ${text}`.toLowerCase();
  if (/asset|balance|overview|equity|wallet|资产|余额|钱包|净值/.test(source)) return "asset-card";
  if (/account|mt4|mt5|live|demo|交易账号|真实|模拟|杠杆/.test(source)) return "account-card";
  if (/quick|action|deposit|withdraw|transfer|入金|出金|转账|快捷/.test(source)) return "action-card";
  if (/progress|step|kyc|onboarding|开户|认证|进度/.test(source)) return "onboarding-card";
  if (/chart|trend|performance|pnl|收益|曲线|表现/.test(source)) return "chart-card";
  if (/copy|signal|leader|跟单|信号/.test(source)) return "copytrading-card";
  if (/referral|invite|ib|推广|邀请/.test(source)) return "referral-card";
  if (/faq|help|support|客服|帮助|问题/.test(source)) return "support-card";
  return /table|row|list|item|列表|明细/.test(source) ? "list-card" : "content-card";
}

function cssRulesForClassNames(css = "", classNames = []) {
  const selected = [];
  const classes = (Array.isArray(classNames) ? classNames : []).slice(0, 8).map((item) => String(item || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!classes.length) return selected;
  const pattern = new RegExp(`(^|})\\s*[^{}]*\\.(${classes.join("|")})(?:[\\s.#:[>{,+~]|\\b)[^{]*\\{([^{}]{0,900})\\}`, "gi");
  for (const match of String(css || "").matchAll(pattern)) {
    selected.push(cleanText(match[0].replace(/^}/, ""), "", 900));
    if (selected.length >= 8) break;
  }
  return uniqueCleanValues(selected, 8, 900);
}

function extractGoldenComponentCards(files = [], htmlStructure = {}, css = "") {
  const html = files.filter((file) => file.type === "html").map((file) => contentOnlyReferenceHtml(file.textContent)).join("\n");
  if (!html.trim()) return [];
  const cards = [];
  const elementPattern = /<(section|article|li|div)\b([^>]*)>([\s\S]{0,4200}?)<\/\1>/gi;
  for (const match of html.matchAll(elementPattern)) {
    const tag = match[1].toLowerCase();
    const attrs = match[2] || "";
    const body = match[3] || "";
    const className = htmlAttributeValue(attrs, "class");
    const dataHook = matchCleanValues(attrs, /\b(data-[\w-]+)\s*=\s*["']?([^"'\s>]+)/gi, 8, (item) => `${item[1]}=${item[2]}`, 100);
    const visibleText = cleanText(stripHtmlTags(body), "", 360);
    const candidateText = `${className} ${dataHook.join(" ")} ${visibleText}`;
    const hasCardSignal = /card|panel|tile|widget|module|section|account|wallet|balance|overview|quick|action|progress|table|list|row|item|asset|feature|metric|账户|资产|钱包|快捷|开户|进度|交易|列表|卡片|面板/i.test(candidateText);
    const hasStructure = /<(h[1-4]|strong|button|a|table|ul|ol|dl)\b/i.test(body);
    if (!hasCardSignal && !hasStructure) continue;
    const heading = matchCleanValues(body, /<(h[1-4]|strong|summary)\b[^>]*>([\s\S]{1,180}?)<\/\1>/gi, 2, (item) => stripHtmlTags(item[2]), 80)[0] || visibleText.split(/[。.!?\n]/)[0] || "样本卡片";
    const classNames = className.split(/\s+/).filter(Boolean).slice(0, 8);
    const styleRules = cssRulesForClassNames(css, classNames);
    const metrics = matchCleanValues(visibleText, /(?:[$€¥]?\s?\d[\d,.]*%?|[A-Z]{2,6}\s?\d[\d,.]*)/g, 8, (item) => item[0], 40);
    cards.push({
      id: `sample-card-${cards.length + 1}`,
      tag,
      role: classifyGoldenComponentCard(className, visibleText),
      heading: cleanText(heading, "样本卡片", 80),
      classNames,
      dataHooks: dataHook,
      visibleText: cleanText(visibleText, "", 320),
      metrics,
      styleRules,
    });
    if (cards.length >= 12) break;
  }
  if (cards.length) return cards;
  return htmlStructure.headings.slice(0, 6).map((heading, index) => ({
    id: `sample-heading-${index + 1}`,
    tag: "section",
    role: "content-section",
    heading,
    classNames: [],
    dataHooks: [],
    visibleText: heading,
    metrics: [],
    styleRules: [],
  }));
}

function extractGoldenCssSummary(files = [], htmlStructure = {}) {
  const css = goldenCssTextFromFiles(files);
  const imageColors = files.flatMap((file) => file.dominantColors || []);
  const colors = uniqueCleanValues(
    [
      ...matchCleanValues(css, /#[0-9a-f]{3,8}\b|rgba?\([^)]+\)|hsla?\([^)]+\)|var\(--[\w-]+\)/gi, 36, (match) => match[0], 40),
      ...imageColors,
    ],
    24,
    40,
  );
  const spacingScale = uniqueCleanValues(
    [
      ...cssDeclarationValues(css, "gap|row-gap|column-gap|padding|padding-inline|padding-block|margin|margin-inline|margin-block|inset|top|right|bottom|left", 28),
      ...matchCleanValues(css, /\b(?:min-|max-)?(?:width|height)\s*:\s*([^;}]+)/gi, 10, (match) => match[1], 80),
    ],
    24,
    80,
  );
  const radiusScale = cssDeclarationValues(css, "border-radius", 16);
  const shadowStyle = cssDeclarationValues(css, "box-shadow|filter", 12);
  const fontScale = cssDeclarationValues(css, "font-size|line-height|font-weight|font-family", 20);
  const cssVariables = extractGoldenCssVariables(css);
  const layoutTokens = extractGoldenLayoutTokens(css, htmlStructure);
  const componentCards = extractGoldenComponentCards(files, htmlStructure, css);
  const layoutSignals = uniqueCleanValues(
    [
      /display\s*:\s*grid/i.test(css) ? "grid layout" : "",
      /display\s*:\s*flex/i.test(css) ? "flex layout" : "",
      /grid-template-columns/i.test(css) ? "explicit grid columns" : "",
      /position\s*:\s*sticky/i.test(css) ? "sticky context" : "",
      /@media/i.test(css) ? "responsive media queries" : "",
      /\b(clamp|minmax|container-type)\b/i.test(css) ? "responsive sizing tokens" : "",
      htmlStructure.tags.includes("nav") ? "navigation present" : "",
      htmlStructure.sectionCount >= 4 ? "multi-section page" : "",
      componentCards.length >= 3 ? "component card inventory" : "",
    ],
    10,
    80,
  );
  const componentStyleNotes = uniqueCleanValues(
    [
      /border\s*:\s*1px/i.test(css) ? "薄边框卡片" : "",
      /backdrop-filter|blur\(/i.test(css) ? "玻璃/模糊背景" : "",
      /linear-gradient|radial-gradient/i.test(css) ? "渐变背景或状态底色" : "",
      /box-shadow/i.test(css) ? "阴影层级" : "",
      /border-radius/i.test(css) ? "统一圆角系统" : "",
      /button|btn|cta/i.test(`${css} ${htmlStructure.classNames.join(" ")}`) ? "明确 CTA / button 层级" : "",
      /card|panel|tile|widget/i.test(`${css} ${htmlStructure.classNames.join(" ")}`) ? "卡片/面板组件语言" : "",
      /table|list|row/i.test(`${css} ${htmlStructure.classNames.join(" ")}`) ? "列表/行式信息组件" : "",
      componentCards.some((card) => card.metrics.length) ? "真实指标/数值卡片" : "",
    ],
    10,
    90,
  );
  return {
    hasCss: Boolean(css.trim()),
    colorPalette: colors,
    spacingScale,
    radiusScale,
    shadowStyle,
    fontScale,
    cssVariables,
    layoutTokens,
    componentCards,
    layoutSignals,
    componentStyleNotes,
    cssLength: css.length,
  };
}

function detectGoldenHomeComponents(searchText = "", htmlStructure = {}) {
  const specs = [
    { name: "资产总览", pattern: /资产|balance|equity|账户余额|总览|overview|净值|余额/, modules: ["asset_overview"], data: ["balance", "equity", "walletTotal"], actions: ["查看资产", "入金"] },
    { name: "钱包列表", pattern: /钱包|wallet|多币种|usd|usdt|xau|eur/, modules: ["wallet_list"], data: ["currency", "availableBalance"], actions: ["转账", "出入金"] },
    { name: "交易账号", pattern: /交易账号|account|mt4|mt5|真实账户|模拟账户|leverage|杠杆/, modules: ["trading_accounts"], data: ["accountId", "balance", "leverage"], actions: ["开新账户", "切换账户"] },
    { name: "开户进度", pattern: /开户进度|kyc|身份认证|onboarding|progress|完成资料|首次入金|新客/, modules: ["onboarding_guide"], data: ["stepStatus", "progress"], actions: ["继续完成", "去认证"] },
    { name: "快捷操作", pattern: /快捷|quick|入金|出金|转账|deposit|withdraw|transfer/, modules: ["quick_actions"], data: ["actionName", "actionStatus"], actions: ["入金", "出金", "转账"] },
    { name: "交易表现", pattern: /盈亏|收益|performance|positions|orders|chart|曲线|趋势/, modules: ["performance_summary"], data: ["pnl", "drawdown", "positions"], actions: ["查看报表"] },
    { name: "邀请推广", pattern: /邀请|referral|refer|ib|代理|推广|邀请码/, modules: ["referral_panel"], data: ["inviteCode", "commission", "conversion"], actions: ["复制链接", "查看推广"] },
    { name: "活动增长", pattern: /活动|campaign|bonus|reward|奖励|挑战赛|promo/, modules: ["campaign_banner"], data: ["reward", "deadline", "progress"], actions: ["查看活动", "领取奖励"] },
    { name: "资金安全", pattern: /安全|风控|security|risk|白标|保证金|隔离|监管/, modules: ["security_trust"], data: ["riskLevel", "margin", "fundSafety"], actions: ["查看安全说明"] },
    { name: "CopyTrading", pattern: /copy\s?trading|跟单|复制交易|leaderboard|排行榜|signal/, modules: ["copy_trading"], data: ["leader", "return", "followers"], actions: ["查看策略", "跟单"] },
  ];
  const detected = specs
    .filter((spec) => spec.pattern.test(searchText))
    .map((spec) => ({
      name: spec.name,
      objective: `${spec.name}在样本中形成了可复用的首页功能组件。`,
      modules: spec.modules,
      data: spec.data,
      actions: spec.actions,
      states: ["default", "hover", "empty"].filter((state) => searchText.includes(state) || state === "default"),
    }));
  if (detected.length) return detected.slice(0, 8);
  return htmlStructure.headings.slice(0, 4).map((heading, index) => ({
    name: heading,
    objective: "从页面标题和区块结构推断的首页内容模块。",
    modules: [`sample_section_${index + 1}`],
    data: [],
    actions: [],
    states: ["default"],
  }));
}

function inferGoldenScenarioTags(searchText = "", metadata = {}) {
  return uniqueCleanValues(
    [
      ...(Array.isArray(metadata.scenarioTags) ? metadata.scenarioTags : []),
      /开户进度|kyc|身份认证|onboarding|新客|完成资料|首次入金/.test(searchText) ? "新客开户" : "",
      /资产|钱包|wallet|balance|overview|默认首页/.test(searchText) ? "默认资产首页" : "",
      /入金|充值|deposit|fund|top up/.test(searchText) ? "入金转化" : "",
      /出金|提现|withdraw|withdrawal/.test(searchText) ? "出金安全" : "",
      /交易|account|mt4|mt5|position|order|盈亏|performance|trader/.test(searchText) ? "专业交易" : "",
      /多账户|账户矩阵|account switch|account list|sub-account/.test(searchText) ? "多账户管理" : "",
      /copy\s?trading|跟单|排行榜|leaderboard|signal/.test(searchText) ? "CopyTrading" : "",
      /pamm|mam|理财|资管|wealth|managed account/.test(searchText) ? "PAMM 理财" : "",
      /ib|代理|推广|referral|refer|邀请/.test(searchText) ? "IB 推广" : "",
      /返佣|佣金|rebate|commission/.test(searchText) ? "返佣中心" : "",
      /vip|黑金|gold|private|高净值|premium/.test(searchText) ? "黑金 VIP" : "",
      /活动|campaign|bonus|reward|奖励|promo/.test(searchText) ? "活动增长" : "",
      /竞赛|比赛|competition|contest/.test(searchText) ? "交易竞赛" : "",
      /风控|合规|监管|risk|compliance/.test(searchText) ? "风控合规" : "",
      /极简|minimal|white|留白|clean/.test(searchText) ? "极简白" : "",
      /暗色|深色|dark|blackgold/.test(searchText) ? "暗色高端" : "",
      /mobile|移动端|手机|单列/.test(searchText) ? "移动端优先" : "",
      /安全|白标|资金安全|security|risk|监管/.test(searchText) ? "白标资金安全" : "",
      /客服|帮助|support|help|工单|ticket/.test(searchText) ? "客服帮助" : "",
      /行情|资讯|news|calendar|财经日历/.test(searchText) ? "行情资讯" : "",
      /本地化|多语言|language|locale|region/.test(searchText) ? "本地化运营" : "",
    ],
    16,
    36,
  ).filter((tag) => HOME_SCENARIO_TAGS.includes(tag));
}

function inferGoldenPageIntent(searchText = "", metadata = {}) {
  const explicit = cleanText(metadata.pageIntent, "", 60);
  if (explicit) return explicit;
  if (/vip|黑金|gold|private|高净值|premium/.test(searchText)) return "vip";
  if (/开户进度|kyc|身份认证|onboarding|新客|完成资料|首次入金/.test(searchText)) return "onboarding";
  if (/ib|代理|推广|referral|refer|邀请/.test(searchText)) return "ib";
  if (/copy\s?trading|跟单|leaderboard/.test(searchText)) return "copyTrading";
  if (/交易|account|mt4|mt5|position|order|trader|盈亏/.test(searchText)) return "trader";
  return "homepage";
}

function inferGoldenThemePreset(searchText = "", cssSummary = {}, metadata = {}) {
  const explicit = cleanText(metadata.themePreset, "", 60);
  if (explicit) return explicit;
  const palette = (cssSummary.colorPalette || []).join(" ").toLowerCase();
  const combined = `${searchText} ${palette}`;
  if (/(黑金|gold|#b7791f|#f5c66b|#d4af37|premium)/.test(combined) && /(#000|#111|black|黑|dark)/.test(combined)) return "blackGold";
  if (/(security|安全|trust|资金|#2563eb|#1d4ed8|blue)/.test(combined)) return "trustBlue";
  if (/(dark|#000|#111827|#0f172a|石墨|terminal)/.test(combined)) return "darkPro";
  if (/(minimal|极简|white|#fff|#ffffff|留白|clean)/.test(combined)) return "minimalWhite";
  return "balancedFintech";
}

function inferGoldenVisualStyle(searchText = "", cssSummary = {}, metadata = {}) {
  const explicit = cleanText(metadata.visualStyle, "", 80);
  if (explicit) return explicit;
  const parts = [
    inferGoldenThemePreset(searchText, cssSummary, {}),
    cssSummary.layoutSignals?.includes("grid layout") ? "grid dashboard" : cssSummary.layoutSignals?.includes("flex layout") ? "flex composition" : "structured homepage",
    cssSummary.componentStyleNotes?.includes("列表/行式信息组件") ? "list-card components" : "",
    cssSummary.spacingScale?.length >= 4 ? "tokenized spacing" : "",
  ].filter(Boolean);
  return cleanText(parts.join(" / "), "fintech homepage visual reference", 80);
}

function buildGoldenSampleBlocks(functions = [], cssSummary = {}, htmlStructure = {}) {
  const notes = uniqueCleanValues([...(cssSummary.layoutSignals || []), ...(cssSummary.componentStyleNotes || [])], 6, 90);
  const blocks = functions.slice(0, 8).map((item, index) => ({
    name: item.name,
    page: index === 0 ? "first-screen" : "content-section",
    function: item.objective,
    componentRefs: [],
    visualNotes: notes,
    dataFields: item.data || [],
  }));
  const cardBlocks = (Array.isArray(cssSummary.componentCards) ? cssSummary.componentCards : []).slice(0, 8).map((card, index) => ({
    id: card.id || `sample-card-${index + 1}`,
    name: card.heading || card.role || `组件卡片 ${index + 1}`,
    page: index === 0 ? "first-screen" : "content-section",
    function: `从样本 HTML 中提取的 ${card.role || "组件卡片"}，用于学习卡片边界、内容密度和字段层级。`,
    componentRefs: [],
    visualNotes: uniqueCleanValues([card.role, ...(card.classNames || []), ...(notes || [])], 8, 90),
    dataFields: card.metrics || [],
  }));
  if (blocks.length || cardBlocks.length) return blocks.concat(cardBlocks).slice(0, 12);
  return [
    {
      name: htmlStructure.headings[0] || "页面视觉骨架",
      page: "full-page",
      function: "从外部样本提取首页骨架、信息层级和视觉 token。",
      componentRefs: [],
      visualNotes: notes,
      dataFields: [],
    },
  ];
}

function inferGoldenScoreDimensions(files = [], htmlStructure = {}, cssSummary = {}, functions = []) {
  const hasImage = files.some((file) => file.type === "image");
  const hasHtml = htmlStructure.hasHtml;
  const hasCss = cssSummary.hasCss;
  const hasResponsive = (cssSummary.layoutSignals || []).some((item) => /responsive|media/i.test(item));
  return {
    firstScreenFocus: hasImage || htmlStructure.headings.length ? 9 : 8,
    informationHierarchy: htmlStructure.headings.length >= 3 || htmlStructure.sectionCount >= 3 ? 9 : 8,
    moduleBalance: cssSummary.layoutSignals?.length >= 2 || functions.length >= 3 ? 9 : 8,
    componentCraft: hasCss && cssSummary.componentStyleNotes?.length >= 3 ? 9 : hasCss ? 8 : 7,
    financialTone: functions.length >= 2 ? 9 : 8,
    businessTruth: functions.length >= 2 || hasHtml ? 8 : 7,
    responsive: hasResponsive ? 9 : hasImage || hasHtml ? 8 : 7,
    visualConsistency: cssSummary.colorPalette?.length || cssSummary.spacingScale?.length ? 9 : 8,
    publishability: hasHtml || hasImage ? 8 : 7,
  };
}

function buildGoldenSampleAnalysis(payload = {}) {
  const metadata = payload.metadata && typeof payload.metadata === "object" ? payload.metadata : {};
  const files = (Array.isArray(payload.files) ? payload.files : [])
    .slice(0, GOLDEN_SAMPLE_ANALYSIS_FILE_LIMIT)
    .map(normalizeGoldenAnalysisFile)
    .filter((file) => file.name || file.textContent || file.type === "image");
  if (!files.length) {
    throw Object.assign(new Error("请先上传 1-3 个图片、HTML、CSS 或 JS 文件"), { statusCode: 400 });
  }
  const htmlStructure = extractGoldenHtmlStructure(files);
  const cssSummary = extractGoldenCssSummary(files, htmlStructure);
  const searchText = goldenAnalysisSearchText(files, metadata);
  const functions = detectGoldenHomeComponents(searchText, htmlStructure);
  const sampleBlocks = buildGoldenSampleBlocks(functions, cssSummary, htmlStructure);
  const scenarioTags = inferGoldenScenarioTags(searchText, metadata);
  const pageIntent = inferGoldenPageIntent(searchText, metadata);
  const themePreset = inferGoldenThemePreset(searchText, cssSummary, metadata);
  const visualStyle = inferGoldenVisualStyle(searchText, cssSummary, metadata);
  const imageFiles = files.filter((file) => file.type === "image");
  const layoutSummary = uniqueCleanValues(
    [
      imageFiles.map((file) => [file.name, file.layoutHint, file.width && file.height ? `${file.width}x${file.height}` : ""].filter(Boolean).join(" · ")).join("；"),
      htmlStructure.tags.length ? `DOM 骨架：${htmlStructure.tags.join(" / ")}` : "",
      htmlStructure.sectionCount ? `区块数量约 ${htmlStructure.sectionCount}` : "",
      cssSummary.layoutSignals?.length ? `布局信号：${cssSummary.layoutSignals.join("、")}` : "",
    ],
    6,
    180,
  );
  const goodPatterns = uniqueCleanValues(
    [
      layoutSummary[0] ? `学习整体骨架：${layoutSummary[0]}` : "",
      cssSummary.spacingScale?.length ? `学习间距/留白 token：${cssSummary.spacingScale.slice(0, 6).join(" / ")}` : "",
      cssSummary.colorPalette?.length ? `学习主色与中性色关系：${cssSummary.colorPalette.slice(0, 6).join(" / ")}` : "",
      cssSummary.componentStyleNotes?.length ? `学习组件工艺：${cssSummary.componentStyleNotes.join("、")}` : "",
      functions.length ? `学习功能组件组织：${functions.map((item) => item.name).slice(0, 6).join("、")}` : "",
      htmlStructure.headings.length ? `学习标题层级：${htmlStructure.headings.slice(0, 6).join(" / ")}` : "",
    ],
    10,
    140,
  );
  const avoidPatterns = uniqueCleanValues(
    [
      "不要像素级复刻原稿布局",
      "不要照搬品牌 Logo、图片、插画和受保护素材",
      "不要复制原稿里的具体金额、姓名、账户、活动文案",
      files.some((file) => file.type === "js") ? "JS 只作为交互意图参考，不把外部脚本直接带入首页生成" : "",
    ],
    8,
    120,
  );
  const name = cleanText(metadata.name, "", 80) || cleanText(files[0]?.name?.replace(/\.[^.]+$/, ""), "自动提取黄金样本", 80);
  const prompt = cleanText(
    metadata.prompt,
    `适合 ${scenarioTags.slice(0, 3).join("、") || pageIntent} 的首页生成参考：学习它的页面骨架、信息层级、间距留白、组件样式和金融产品气质。`,
    900,
  );
  return {
    source: "local-golden-sample-extractor",
    aiSupplementStatus: "reserved",
    name,
    prompt,
    pageIntent,
    themePreset,
    visualStyle,
    scenarioTags,
    applicableScenarios: uniqueCleanValues([...(Array.isArray(metadata.applicableScenarios) ? metadata.applicableScenarios : []), ...scenarioTags, pageIntent], 10, 80),
    humanScore: Number.isFinite(Number(metadata.humanScore)) ? Math.max(0, Math.min(100, Math.round(Number(metadata.humanScore)))) : 92,
    scoreDimensions: inferGoldenScoreDimensions(files, htmlStructure, cssSummary, functions),
    page: {
      name,
      layout: cleanText(layoutSummary.join("；") || "本地自动提取的 visual-only 首页骨架。", "", 180),
      hero: cleanText(goodPatterns[0] || "学习首屏焦点、模块比例和信息层级。", "", 180),
      navigation: cleanText(htmlStructure.tags.includes("nav") ? "包含导航/顶部操作，可学习其层级和压缩方式。" : htmlStructure.headings.slice(0, 4).join(" / "), "", 140),
      mobile: cleanText(cssSummary.layoutSignals?.some((item) => /responsive|media/i.test(item)) ? "包含响应式断点或自适应尺寸，可学习移动端单列节奏。" : imageFiles.some((file) => file.height > file.width) ? "图片接近移动端比例，可学习移动端首屏节奏。" : "", "", 160),
    },
    functions,
    sampleBlocks,
    goodPatterns,
    avoidPatterns,
    whyGood: cleanText(goodPatterns.join("；"), "它提供了可学习的整页骨架、视觉 token 和功能组件组织。", 900),
    whyBad: "",
    forbiddenReuse: cleanText(avoidPatterns.join("；"), "", 900),
    cssSummary: {
      ...cssSummary,
      htmlStructure,
      sourceFiles: files.map((file) => ({
        name: file.name,
        type: file.type,
        size: file.size,
        width: file.width,
        height: file.height,
        layoutHint: file.layoutHint,
        dominantColors: file.dominantColors,
      })),
    },
    themeTokens: {
      themePreset,
      visualStyle,
      colorPalette: cssSummary.colorPalette,
      spacingScale: cssSummary.spacingScale,
      radiusScale: cssSummary.radiusScale,
      shadowStyle: cssSummary.shadowStyle,
      fontScale: cssSummary.fontScale,
      cssVariables: cssSummary.cssVariables,
      layoutTokens: cssSummary.layoutTokens,
      componentCards: cssSummary.componentCards,
    },
    domSnapshot: cleanText([htmlStructure.textExcerpt, files.filter((file) => file.type === "js").map((file) => file.textExcerpt).join(" ")].filter(Boolean).join(" "), "", 3000),
    promptSeeds: [prompt, ...htmlStructure.headings].filter(Boolean).slice(0, 8),
    sourceFileSummary: files.map((file) => `${file.name} · ${file.type}${file.width && file.height ? ` · ${file.width}x${file.height}` : ""}`),
  };
}

function jsonCloneWithinLimit(value, fallback, limit = 120_000) {
  if (!value || typeof value !== "object") return fallback;
  try {
    const text = JSON.stringify(value);
    if (text.length <= limit) return JSON.parse(text);
    return {
      truncated: true,
      excerpt: text.slice(0, limit),
      snapshot: value.brickPlan || value.sections ? homepageRecordSnapshot(value) : null,
    };
  } catch (error) {
    return fallback;
  }
}

function normalizeScoreDimensions(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  const aliases = {
    visualFocus: "firstScreenFocus",
    hierarchy: "informationHierarchy",
    brand: "financialTone",
    craft: "componentCraft",
    business: "businessTruth",
    mobile: "responsive",
    layoutHierarchy: "informationHierarchy",
    brandHarmony: "financialTone",
    businessFunction: "businessTruth",
    responsiveSafety: "responsive",
  };
  const normalized = {};
  Object.entries(source).forEach(([key, rawValue]) => {
    const normalizedKey = aliases[key] || key;
    if (!HOME_GOLDEN_SAMPLE_DIMENSIONS.includes(normalizedKey)) return;
    const score = Number(rawValue);
    if (Number.isFinite(score)) normalized[normalizedKey] = Math.max(0, Math.min(10, Math.round(score)));
  });
  return normalized;
}

function normalizeGoldenSampleEvidence(sample = {}) {
  const evidence = sample.renderEvidence && typeof sample.renderEvidence === "object" ? sample.renderEvidence : sample.evidence && typeof sample.evidence === "object" ? sample.evidence : {};
  const cssSummary = evidence.cssSummary && typeof evidence.cssSummary === "object" ? evidence.cssSummary : sample.cssTokenSummary && typeof sample.cssTokenSummary === "object" ? sample.cssTokenSummary : {};
  const themeTokens = evidence.themeTokens && typeof evidence.themeTokens === "object" ? evidence.themeTokens : sample.themeTokens && typeof sample.themeTokens === "object" ? sample.themeTokens : {};
  return {
    screenshotPath: cleanText(evidence.screenshotPath || sample.screenshotPath, "", 280),
    screenshotUrl: cleanText(evidence.screenshotUrl || sample.screenshotUrl, "", 280),
    domSnapshot: safeEvidenceText(evidence.domSnapshot || evidence.renderedDom || sample.domSnapshot, 50_000),
    aiHtml: safeEvidenceText(evidence.aiHtml || sample.aiHtml, 30_000),
    aiCss: safeEvidenceText(evidence.aiCss || sample.aiCss, 30_000),
    cssSummary: jsonCloneWithinLimit(cssSummary, {}, 60_000),
    themeTokens: jsonCloneWithinLimit(themeTokens, {}, 40_000),
    capturedAt: cleanText(evidence.capturedAt || sample.capturedAt, "", 40),
    sourceUrl: cleanText(evidence.sourceUrl || sample.sourceUrl, "", 260),
  };
}

function normalizeDesignSample(sample = {}) {
  const page = sample.page && typeof sample.page === "object" ? sample.page : {};
  const prompt = cleanText(sample.prompt || sample.sourcePrompt || (Array.isArray(sample.promptSeeds) ? sample.promptSeeds[0] : ""), "", 1600);
  const rawKind = cleanText(sample.sampleKind || sample.kind || sample.type, "", 40);
  const isAntiExample = Boolean(sample.isAntiExample || sample.antiExample || rawKind === "anti-example" || rawKind === "low-score");
  const humanScore = Number.isFinite(Number(sample.humanScore ?? sample.manualScore))
    ? Math.max(0, Math.min(100, Math.round(Number(sample.humanScore ?? sample.manualScore))))
    : null;
  const aestheticScore = Number.isFinite(Number(sample.aestheticScore)) ? Math.max(0, Math.min(100, Math.round(Number(sample.aestheticScore)))) : humanScore ?? 88;
  const idHint = cleanText(sample.id || sample.name, "", 100);
  const homepageConfig = jsonCloneWithinLimit(sample.homepageConfig || sample.config || sample.homepageConfigJson, null, 160_000);
  let renderEvidence = normalizeGoldenSampleEvidence(sample);
  const initialSourceType = cleanText(sample.sourceType || sample.sampleSourceType, "", 40);
  const visualOnlyHint = Boolean(
    sample.visualOnly ||
      sample.isVisualOnly ||
      rawKind === "visual-only" ||
      initialSourceType === "visual-only" ||
      /^visual[-_]/i.test(idHint) ||
      /visual-only|仅学习外部设计稿/i.test(page.layout || "") ||
      (!homepageConfig && (renderEvidence.screenshotPath || renderEvidence.screenshotUrl || renderEvidence.sourceUrl || sample.referenceAssetId || sample.sourceReferenceAssetId)),
  );
  const compactAssetName = (value = "") =>
    cleanText(value, "", 120)
      .toLowerCase()
      .replace(/\.[a-z0-9]+$/i, "")
      .replace(/[\s@_\-]+/g, "");
  const sampleCreatedMs = new Date(sample.createdAt || sample.updatedAt || 0).getTime();
  const referenceAssetScore = (asset) => {
    let score = 0;
    if (expectedAssetName && compactAssetName(asset.name) === expectedAssetName) score += 100;
    const assetCreatedMs = new Date(asset.createdAt || asset.at || 0).getTime();
    if (Number.isFinite(sampleCreatedMs) && Number.isFinite(assetCreatedMs)) {
      const deltaMs = Math.abs(sampleCreatedMs - assetCreatedMs);
      if (deltaMs <= 10_000) score += 40;
      else if (deltaMs <= 120_000) score += 16;
    }
    const sampleTags = new Set((Array.isArray(sample.tags) ? sample.tags : []).map((tag) => cleanText(tag, "", 36)).filter(Boolean));
    const overlap = (Array.isArray(asset.tags) ? asset.tags : []).filter((tag) => sampleTags.has(tag)).length;
    score += overlap * 8;
    const hero = cleanText(page.hero || sample.whyGood || "", "", 180);
    if (hero && cleanText(asset.note, "", 180) === hero) score += 30;
    return score;
  };
  const expectedAssetName = compactAssetName(sample.name || page.name);
  const inferredReferenceAsset = visualOnlyHint && !sample.referenceAssetId && !sample.sourceReferenceAssetId
    ? readReferenceAssets()
        .map((asset) => ({ asset, score: referenceAssetScore(asset) }))
        .filter((item) => item.score >= 40)
        .sort((a, b) => b.score - a.score)[0]?.asset || null
    : null;
  if (inferredReferenceAsset && !renderEvidence.screenshotUrl && !renderEvidence.sourceUrl) {
    renderEvidence = {
      ...renderEvidence,
      screenshotPath: inferredReferenceAsset.type === "image" ? inferredReferenceAsset.storagePath || "" : renderEvidence.screenshotPath,
      screenshotUrl: inferredReferenceAsset.type === "image" ? inferredReferenceAsset.url || "" : renderEvidence.screenshotUrl,
      sourceUrl: inferredReferenceAsset.url || renderEvidence.sourceUrl,
      cssSummary: {
        ...(renderEvidence.cssSummary || {}),
        referenceAssetId: inferredReferenceAsset.id,
        referenceType: inferredReferenceAsset.type,
        textExcerpt: inferredReferenceAsset.textExcerpt || "",
      },
    };
  }
  const explicitGolden = Boolean(
    sample.isGolden ||
      sample.golden ||
      sample.primaryReference ||
      sample.visualOnly ||
      sample.isVisualOnly ||
      rawKind === "golden-page" ||
      rawKind === "visual-only" ||
      visualOnlyHint,
  );
  const isGolden = !isAntiExample && (explicitGolden || (rawKind !== "page" && rawKind !== "component" && humanScore !== null && humanScore >= 92));
  const sampleKind = isAntiExample ? "anti-example" : isGolden ? "golden-page" : rawKind === "component" ? "component" : "page";
  const scenarioTags = [
    ...(Array.isArray(sample.scenarioTags) ? sample.scenarioTags : []),
    ...(Array.isArray(sample.tags) ? sample.tags : []).filter((tag) => HOME_SCENARIO_TAGS.includes(tag)),
  ]
    .map((tag) => cleanText(tag, "", 36))
    .filter(Boolean);
  const visualOnly = Boolean(
    sample.visualOnly ||
      sample.isVisualOnly ||
      rawKind === "visual-only" ||
      initialSourceType === "visual-only" ||
      visualOnlyHint ||
      (!homepageConfig && sampleKind === "golden-page" && (renderEvidence.screenshotPath || renderEvidence.screenshotUrl || renderEvidence.sourceUrl || sample.referenceAssetId)),
  );
  const sourceType = visualOnly ? "visual-only" : initialSourceType || (homepageConfig ? "homepage-config" : "sample-notes");
  const themePreset = cleanText(sample.themePreset || sample.configSnapshot?.themePreset || homepageConfig?.themePreset || homepageConfig?.theme || renderEvidence.themeTokens?.themePreset, "", 60);
  const normalizedHumanScore = humanScore ?? (isGolden ? aestheticScore : null);
  return {
    id: safeId(sample.id || sample.name, "design-sample"),
    sampleKind,
    sourceType,
    visualOnly,
    isGolden,
    isAntiExample,
    name: cleanText(sample.name, "首页审美样本", 80),
    scenario: cleanText(sample.scenario || sample.intent || sample.pageIntent, "", 120),
    pageIntent: cleanText(sample.pageIntent || sample.intent, "", 60),
    themePreset,
    visualStyle: cleanText(sample.visualStyle || sample.style, "", 80),
    prompt,
    aestheticScore,
    humanScore: normalizedHumanScore,
    scoreDimensions: normalizeScoreDimensions(sample.scoreDimensions || sample.manualDimensions || sample.dimensions),
    tags: (Array.isArray(sample.tags) ? sample.tags : []).map((tag) => cleanText(tag, "", 36)).filter(Boolean).slice(0, 12),
    scenarioTags: [...new Set(scenarioTags)].slice(0, 16),
    page: {
      name: cleanText(page.name || sample.name, "首页页面", 80),
      layout: cleanText(page.layout, "", 180),
      hero: cleanText(page.hero, "", 180),
      navigation: cleanText(page.navigation, "", 140),
      mobile: cleanText(page.mobile, "", 160),
    },
    functions: (Array.isArray(sample.functions) ? sample.functions : []).map(normalizeDesignFunction).slice(0, 10),
    sampleBlocks: (Array.isArray(sample.sampleBlocks) ? sample.sampleBlocks : []).map(normalizeSampleBlock).slice(0, 12),
    componentRefs: (Array.isArray(sample.componentRefs) ? sample.componentRefs : []).map((id) => cleanText(id, "", 80)).filter(Boolean).slice(0, 12),
    goodPatterns: (Array.isArray(sample.goodPatterns) ? sample.goodPatterns : []).map((item) => cleanText(item, "", 140)).filter(Boolean).slice(0, 10),
    avoidPatterns: (Array.isArray(sample.avoidPatterns) ? sample.avoidPatterns : []).map((item) => cleanText(item, "", 140)).filter(Boolean).slice(0, 10),
    whyGood: cleanText(sample.whyGood || sample.goodReason, "", 900),
    whyBad: cleanText(sample.whyBad || sample.badReason, "", 900),
    applicableScenarios: (Array.isArray(sample.applicableScenarios) ? sample.applicableScenarios : []).map((item) => cleanText(item, "", 80)).filter(Boolean).slice(0, 10),
    forbiddenReuse: cleanText(sample.forbiddenReuse || sample.forbiddenReuseNotes || sample.antiPatternNotes, "", 900),
    homepageConfig,
    configSnapshot: visualOnly ? null : sample.configSnapshot && typeof sample.configSnapshot === "object" ? jsonCloneWithinLimit(sample.configSnapshot, null, 20_000) : homepageConfig ? homepageRecordSnapshot(homepageConfig) : null,
    referenceAssetId: cleanText(sample.referenceAssetId || sample.sourceReferenceAssetId || renderEvidence.cssSummary?.referenceAssetId || inferredReferenceAsset?.id, "", 100),
    sourceAssetType: cleanText(sample.sourceAssetType || renderEvidence.cssSummary?.referenceType || inferredReferenceAsset?.type, "", 40),
    renderEvidence,
    promptSeeds: [...new Set([prompt, ...(Array.isArray(sample.promptSeeds) ? sample.promptSeeds : [])].map((item) => cleanText(item, "", 260)).filter(Boolean))].slice(0, 8),
    createdAt: sample.createdAt || new Date().toISOString(),
    updatedAt: sample.updatedAt || sample.createdAt || new Date().toISOString(),
  };
}

let designSamplesReadCache = null;
let designSampleRankCache = new Map();
let goldenStyleContractCache = new Map();

function readDesignSamples() {
  let mtimeMs = 0;
  try {
    mtimeMs = fs.statSync(DESIGN_SAMPLE_FILE).mtimeMs;
  } catch (error) {
    mtimeMs = 0;
  }
  if (designSamplesReadCache && designSamplesReadCache.mtimeMs === mtimeMs) return designSamplesReadCache.payload;
  const data = readJsonFile(DESIGN_SAMPLE_FILE, { samples: [] });
  const payload = {
    version: Number.isFinite(Number(data.version)) ? Number(data.version) : 1,
    updatedAt: cleanText(data.updatedAt, "", 40) || new Date().toISOString(),
    samples: (Array.isArray(data.samples) ? data.samples : []).map(normalizeDesignSample).slice(0, MAX_DESIGN_SAMPLES),
  };
  designSampleRankCache = new Map();
  goldenStyleContractCache = new Map();
  designSamplesReadCache = { mtimeMs, payload };
  return payload;
}

function writeDesignSamples(samples) {
  const normalized = (Array.isArray(samples) ? samples : []).map(normalizeDesignSample).slice(0, MAX_DESIGN_SAMPLES);
  const payload = { version: 1, updatedAt: new Date().toISOString(), samples: normalized };
  writeJsonFile(DESIGN_SAMPLE_FILE, payload);
  designSamplesReadCache = null;
  designSampleRankCache = new Map();
  goldenStyleContractCache = new Map();
  return payload;
}

function ensureGoldenSampleAssetDir() {
  fs.mkdirSync(GOLDEN_SAMPLE_ASSET_DIR, { recursive: true });
}

function localChromeExecutablePath() {
  const candidates = [
    process.env.CHROME_PATH,
    process.env.GOOGLE_CHROME_BIN,
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
    "/usr/bin/google-chrome-stable",
    "/usr/bin/google-chrome",
    "/usr/bin/chromium-browser",
    "/usr/bin/chromium",
  ].filter(Boolean);
  return candidates.find((candidate) => {
    try {
      fs.accessSync(candidate, fs.constants.X_OK);
      return true;
    } catch (error) {
      return false;
    }
  }) || "";
}

function localAssetPathFromUrl(url = "") {
  const source = cleanText(url, "", 260);
  if (!source || /^https?:\/\//i.test(source) || /^data:/i.test(source)) return "";
  let pathname = source;
  try {
    pathname = new URL(source, "http://local").pathname;
  } catch (error) {
    pathname = source.split(/[?#]/)[0];
  }
  const filePath = path.resolve(mutableStoragePath(decodeURIComponent(pathname).replace(/^\/+/, "")));
  return canAccessMutablePath(filePath, REFERENCE_ASSET_DIR) || canAccessMutablePath(filePath, GOLDEN_SAMPLE_ASSET_DIR) ? filePath : "";
}

function goldenSampleNeedsSourceScreenshot(sample = {}, evidence = {}) {
  if (evidence.screenshotPath || evidence.screenshotUrl) return false;
  const sourceUrl = cleanText(evidence.sourceUrl || sample.sourceUrl, "", 260);
  if (!sourceUrl) return false;
  const sourceType = `${sample.sourceAssetType || evidence.cssSummary?.referenceType || ""} ${sourceUrl}`.toLowerCase();
  return /html|\.html?(?:[?#]|$)/i.test(sourceType);
}

function applyGoldenSampleScreenshotFile(evidence, filePath, fileName, sourceUrl = "", options = {}) {
  const stats = fs.existsSync(filePath) ? fs.statSync(filePath) : null;
  if (!stats || stats.size <= 0) return false;
  evidence.screenshotPath = mutableRelativePath(filePath);
  evidence.screenshotUrl = `/artifacts/home-golden-samples/${fileName}`;
  evidence.screenshotCapturedFrom = sourceUrl;
  if (options.scope) evidence.screenshotScope = options.scope;
  if (Array.isArray(options.excludedChrome)) evidence.screenshotExcludedChrome = options.excludedChrome;
  evidence.capturedAt = evidence.capturedAt || new Date().toISOString();
  return true;
}

function captureGoldenSampleSourceScreenshot(sample = {}) {
  const draft = sample && typeof sample === "object" ? { ...sample } : {};
  const evidence = draft.renderEvidence && typeof draft.renderEvidence === "object" ? { ...draft.renderEvidence } : {};
  if (IS_VERCEL || process.env.HOME_GOLDEN_SCREENSHOT === "off" || !goldenSampleNeedsSourceScreenshot(draft, evidence)) {
    draft.renderEvidence = evidence;
    return draft;
  }

  const sourcePath = localAssetPathFromUrl(evidence.sourceUrl || draft.sourceUrl);
  const chromePath = localChromeExecutablePath();
  if (!sourcePath || !chromePath || !fs.existsSync(sourcePath)) {
    draft.renderEvidence = evidence;
    return draft;
  }

  ensureGoldenSampleAssetDir();
  const id = safeId(draft.id || draft.name, "golden-sample");
  const fileName = `${id}-${Date.now().toString(36)}-preview.png`;
  const filePath = path.join(GOLDEN_SAMPLE_ASSET_DIR, fileName);
  const tempRoot = path.join(os.tmpdir(), `home-golden-shot-${process.pid}-${Date.now().toString(36)}-${Math.random().toString(16).slice(2)}`);
  const userDataDir = path.join(tempRoot, "profile");
  const captureSourcePath = path.join(tempRoot, "content-only.html");
  const screenshotOptions = {
    scope: "content-only",
    excludedChrome: ["sidebar", "topbar", "page-tabs"],
  };
  let captureUrl = pathToFileURL(sourcePath).href;

  try {
    fs.mkdirSync(tempRoot, { recursive: true });
    const sourceHtml = fs.readFileSync(sourcePath, "utf8");
    fs.writeFileSync(captureSourcePath, goldenSampleContentOnlyCaptureHtml(sourceHtml), "utf8");
    captureUrl = pathToFileURL(captureSourcePath).href;
    childProcess.execFileSync(
      chromePath,
      [
        "--headless=new",
        "--disable-gpu",
        "--disable-dev-shm-usage",
        "--disable-background-networking",
        "--disable-component-update",
        "--disable-default-apps",
        "--disable-extensions",
        "--disable-sync",
        "--no-first-run",
        "--no-default-browser-check",
        "--hide-scrollbars",
        "--allow-file-access-from-files",
        "--run-all-compositor-stages-before-draw",
        "--virtual-time-budget=2500",
        `--user-data-dir=${userDataDir}`,
        "--window-size=1440,1100",
        `--screenshot=${filePath}`,
        captureUrl,
      ],
      { timeout: 15000, stdio: "ignore" },
    );
    applyGoldenSampleScreenshotFile(evidence, filePath, fileName, evidence.sourceUrl || draft.sourceUrl || "", screenshotOptions);
  } catch (error) {
    if (!applyGoldenSampleScreenshotFile(evidence, filePath, fileName, evidence.sourceUrl || draft.sourceUrl || "", screenshotOptions)) {
      try {
        if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
      } catch (cleanupError) {
        // Best effort cleanup; the source HTML can still be shown as a fallback.
      }
    }
  } finally {
    try {
      fs.rmSync(tempRoot, { recursive: true, force: true });
    } catch (cleanupError) {
      // Ignore Chrome profile cleanup failures.
    }
  }

  draft.renderEvidence = evidence;
  return draft;
}

function saveGoldenSampleScreenshotAsset(sample = {}) {
  const draft = sample && typeof sample === "object" ? { ...sample } : {};
  const evidence = draft.renderEvidence && typeof draft.renderEvidence === "object" ? { ...draft.renderEvidence } : draft.evidence && typeof draft.evidence === "object" ? { ...draft.evidence } : {};
  const screenshotDataUrl = evidence.screenshotDataUrl || evidence.screenshot || draft.screenshotDataUrl;
  if (!screenshotDataUrl || evidence.screenshotPath) {
    if (draft.renderEvidence) draft.renderEvidence = evidence;
    return draft;
  }

  const decoded = decodeReferenceDataUrl(screenshotDataUrl);
  if (!decoded || !/^image\//i.test(decoded.mime)) {
    delete evidence.screenshotDataUrl;
    delete evidence.screenshot;
    draft.renderEvidence = evidence;
    return draft;
  }
  if (decoded.buffer.length > 6_000_000) {
    throw Object.assign(new Error("黄金样本截图不能超过 6MB"), { statusCode: 413 });
  }

  ensureGoldenSampleAssetDir();
  const ext = referenceAssetExtension(decoded.mime, "golden-sample.png");
  const id = safeId(draft.id || draft.name, "golden-sample");
  const fileName = `${id}-${Date.now().toString(36)}.${ext}`;
  const filePath = path.join(GOLDEN_SAMPLE_ASSET_DIR, fileName);
  fs.writeFileSync(filePath, decoded.buffer);
  delete evidence.screenshotDataUrl;
  delete evidence.screenshot;
  evidence.screenshotPath = mutableRelativePath(filePath);
  evidence.screenshotUrl = `/artifacts/home-golden-samples/${fileName}`;
  draft.renderEvidence = evidence;
  return draft;
}

function referenceAssetStorageFile(asset = {}) {
  const storagePath = cleanText(asset.storagePath, "", 260);
  if (!storagePath) return "";
  const filePath = path.resolve(mutableStoragePath(storagePath));
  return canAccessMutablePath(filePath, REFERENCE_ASSET_DIR) && fs.existsSync(filePath) ? filePath : "";
}

function linkedCssFilesForHtmlSource(htmlPath = "", html = "") {
  const baseDir = path.dirname(htmlPath);
  const files = [];
  for (const match of String(html || "").matchAll(/<link\b[^>]*href\s*=\s*["']([^"']+\.css(?:[?#][^"']*)?)["'][^>]*>/gi)) {
    const href = cleanText(match[1], "", 260);
    if (!href || /^(?:https?:)?\/\//i.test(href) || /^data:/i.test(href)) continue;
    let candidate = "";
    try {
      candidate = path.resolve(baseDir, decodeURIComponent(href.split(/[?#]/)[0]));
    } catch (error) {
      candidate = "";
    }
    if (!candidate || !candidate.startsWith(`${baseDir}${path.sep}`) || !fs.existsSync(candidate)) continue;
    const css = sanitizeGeneratedCss(fs.readFileSync(candidate, "utf8"));
    files.push({
      name: path.basename(candidate),
      mime: "text/css",
      type: "css",
      size: Buffer.byteLength(css, "utf8"),
      textContent: css,
      textExcerpt: cleanText(css, "", 900),
    });
    if (files.length >= 4) break;
  }
  return files;
}

function goldenAnalysisFileFromPath(filePath = "", name = "") {
  if (!filePath || !fs.existsSync(filePath)) return null;
  const fileName = cleanText(name || path.basename(filePath), "golden-source", 120);
  const type = goldenAnalysisFileType({ name: fileName, mime: "" });
  if (!["html", "css", "js"].includes(type)) return null;
  const rawText = fs.readFileSync(filePath, "utf8");
  const textContent =
    type === "html"
      ? sanitizeReferenceDocumentHtml(rawText)
      : type === "css"
        ? sanitizeGeneratedCss(rawText)
        : rawText.slice(0, 80_000);
  return {
    name: fileName,
    mime: type === "html" ? "text/html" : type === "css" ? "text/css" : "text/javascript",
    type,
    size: Buffer.byteLength(textContent, "utf8"),
    textContent,
    textExcerpt: cleanText(stripHtmlTags(type === "html" ? contentOnlyReferenceHtml(textContent) : textContent), "", 900),
  };
}

function goldenSampleSourceAssetIds(sample = {}, evidence = {}) {
  const cssSummary = evidence.cssSummary && typeof evidence.cssSummary === "object" ? evidence.cssSummary : {};
  return [
    sample.referenceAssetId,
    sample.sourceReferenceAssetId,
    cssSummary.referenceAssetId,
    ...(Array.isArray(cssSummary.sourceAssetIds) ? cssSummary.sourceAssetIds : []),
  ]
    .map((id) => cleanText(id, "", 100))
    .filter(Boolean);
}

function goldenSampleAnalysisFilesFromSources(sample = {}) {
  const evidence = sample.renderEvidence && typeof sample.renderEvidence === "object" ? sample.renderEvidence : {};
  const assetIds = new Set(goldenSampleSourceAssetIds(sample, evidence));
  const assets = readReferenceAssets().filter((asset) => assetIds.has(asset.id));
  const files = [];
  assets.forEach((asset) => {
    const filePath = referenceAssetStorageFile(asset);
    const file = goldenAnalysisFileFromPath(filePath, asset.name);
    if (file) {
      files.push(file);
      if (file.type === "html") files.push(...linkedCssFilesForHtmlSource(filePath, file.textContent));
    }
  });
  const sourcePath = localAssetPathFromUrl(evidence.sourceUrl || sample.sourceUrl);
  const sourceFile = goldenAnalysisFileFromPath(sourcePath, path.basename(sourcePath || ""));
  if (sourceFile && !files.some((file) => file.name === sourceFile.name && file.size === sourceFile.size)) {
    files.push(sourceFile);
    if (sourceFile.type === "html") files.push(...linkedCssFilesForHtmlSource(sourcePath, sourceFile.textContent));
  }
  return files.slice(0, GOLDEN_SAMPLE_ANALYSIS_FILE_LIMIT);
}

function mergeGoldenTokenArrays(primary = [], secondary = [], limit = 24) {
  return uniqueCleanValues([...(Array.isArray(primary) ? primary : []), ...(Array.isArray(secondary) ? secondary : [])], limit, 160);
}

function enrichGoldenSampleFromSourceFiles(sample = {}) {
  const draft = sample && typeof sample === "object" ? { ...sample } : {};
  const rawKind = cleanText(draft.sampleKind || draft.kind || draft.type, "", 40);
  const sourceType = cleanText(draft.sourceType || draft.sampleSourceType, "", 40);
  const evidence = draft.renderEvidence && typeof draft.renderEvidence === "object" ? { ...draft.renderEvidence } : {};
  const shouldEnrich = Boolean(
    draft.isGolden ||
      draft.visualOnly ||
      rawKind === "golden-page" ||
      rawKind === "visual-only" ||
      sourceType === "visual-only" ||
      evidence.sourceUrl ||
      goldenSampleSourceAssetIds(draft, evidence).length,
  );
  if (!shouldEnrich) return draft;
  const files = goldenSampleAnalysisFilesFromSources({ ...draft, renderEvidence: evidence });
  if (!files.length) return draft;
  let analysis = null;
  try {
    analysis = buildGoldenSampleAnalysis({
      files,
      metadata: {
        name: draft.name,
        prompt: draft.prompt,
        pageIntent: draft.pageIntent,
        themePreset: draft.themePreset,
        visualStyle: draft.visualStyle,
        scenarioTags: draft.scenarioTags,
        applicableScenarios: draft.applicableScenarios,
        humanScore: draft.humanScore,
        scoreDimensions: draft.scoreDimensions,
      },
    });
  } catch (error) {
    return draft;
  }
  const existingCss = evidence.cssSummary && typeof evidence.cssSummary === "object" ? evidence.cssSummary : {};
  const analysisCss = analysis.cssSummary && typeof analysis.cssSummary === "object" ? analysis.cssSummary : {};
  const existingTokens = evidence.themeTokens && typeof evidence.themeTokens === "object" ? evidence.themeTokens : {};
  const analysisTokens = analysis.themeTokens && typeof analysis.themeTokens === "object" ? analysis.themeTokens : {};
  const cssSummary = {
    ...analysisCss,
    ...existingCss,
    colorPalette: mergeGoldenTokenArrays(analysisCss.colorPalette, existingCss.colorPalette, 30),
    spacingScale: mergeGoldenTokenArrays(analysisCss.spacingScale, existingCss.spacingScale, 30),
    radiusScale: mergeGoldenTokenArrays(analysisCss.radiusScale, existingCss.radiusScale, 20),
    shadowStyle: mergeGoldenTokenArrays(analysisCss.shadowStyle, existingCss.shadowStyle, 16),
    fontScale: mergeGoldenTokenArrays(analysisCss.fontScale, existingCss.fontScale, 24),
    componentStyleNotes: mergeGoldenTokenArrays(analysisCss.componentStyleNotes, existingCss.componentStyleNotes, 12),
    layoutSignals: mergeGoldenTokenArrays(analysisCss.layoutSignals, existingCss.layoutSignals, 12),
    cssVariables: {
      ...(analysisCss.cssVariables || {}),
      ...(existingCss.cssVariables || {}),
    },
    layoutTokens: {
      ...(analysisCss.layoutTokens || {}),
      ...(existingCss.layoutTokens || {}),
    },
    componentCards: (Array.isArray(existingCss.componentCards) && existingCss.componentCards.length ? existingCss.componentCards : analysisCss.componentCards || []).slice(0, 12),
    htmlStructure: analysisCss.htmlStructure || existingCss.htmlStructure || {},
    sourceFiles: (analysisCss.sourceFiles || existingCss.sourceFiles || []).slice(0, 8),
    sourceExtractionStatus: "auto-extracted",
    sourceExtractionAt: new Date().toISOString(),
  };
  const themeTokens = {
    ...analysisTokens,
    ...existingTokens,
    colorPalette: mergeGoldenTokenArrays(analysisTokens.colorPalette, existingTokens.colorPalette, 30),
    spacingScale: mergeGoldenTokenArrays(analysisTokens.spacingScale, existingTokens.spacingScale, 30),
    radiusScale: mergeGoldenTokenArrays(analysisTokens.radiusScale, existingTokens.radiusScale, 20),
    shadowStyle: mergeGoldenTokenArrays(analysisTokens.shadowStyle, existingTokens.shadowStyle, 16),
    fontScale: mergeGoldenTokenArrays(analysisTokens.fontScale, existingTokens.fontScale, 24),
    cssVariables: {
      ...(analysisTokens.cssVariables || {}),
      ...(existingTokens.cssVariables || {}),
    },
    layoutTokens: {
      ...(analysisTokens.layoutTokens || {}),
      ...(existingTokens.layoutTokens || {}),
    },
    componentCards: (Array.isArray(existingTokens.componentCards) && existingTokens.componentCards.length ? existingTokens.componentCards : analysisTokens.componentCards || []).slice(0, 12),
  };
  draft.renderEvidence = {
    ...evidence,
    domSnapshot: evidence.domSnapshot || analysis.domSnapshot || "",
    cssSummary,
    themeTokens,
  };
  if (!Array.isArray(draft.functions) || !draft.functions.length) draft.functions = analysis.functions || [];
  if (!Array.isArray(draft.sampleBlocks) || !draft.sampleBlocks.length) draft.sampleBlocks = analysis.sampleBlocks || [];
  else {
    draft.sampleBlocks = draft.sampleBlocks.concat((analysis.sampleBlocks || []).filter((block) => !draft.sampleBlocks.some((item) => item.id && item.id === block.id))).slice(0, 12);
  }
  if (!Array.isArray(draft.goodPatterns) || !draft.goodPatterns.length) draft.goodPatterns = analysis.goodPatterns || [];
  if (!Array.isArray(draft.promptSeeds) || !draft.promptSeeds.length) draft.promptSeeds = analysis.promptSeeds || [];
  if (!draft.visualStyle) draft.visualStyle = analysis.visualStyle || "";
  if (!draft.themePreset) draft.themePreset = analysis.themePreset || "";
  if (!draft.pageIntent) draft.pageIntent = analysis.pageIntent || "";
  return draft;
}

function prepareDesignSampleForSave(sample = {}) {
  const withScreenshotAsset = saveGoldenSampleScreenshotAsset(sample);
  const enriched = enrichGoldenSampleFromSourceFiles(withScreenshotAsset);
  return captureGoldenSampleSourceScreenshot(enriched);
}

function saveDesignSample(sample) {
  const library = readDesignSamples();
  const normalized = normalizeDesignSample(prepareDesignSampleForSave(sample));
  return {
    sample: normalized,
    library: writeDesignSamples(library.samples.filter((item) => item.id !== normalized.id).concat(normalized)),
  };
}

function updateDesignSample(id, updates = {}) {
  const library = readDesignSamples();
  const normalizedId = safeId(id, "design-sample");
  const index = library.samples.findIndex((sample) => sample.id === normalizedId);
  if (index < 0) {
    throw Object.assign(new Error("Design sample not found"), { statusCode: 404 });
  }
  const existing = library.samples[index];
  const merged = {
    ...existing,
    ...(updates && typeof updates === "object" ? updates : {}),
    id: existing.id,
    createdAt: existing.createdAt,
    updatedAt: new Date().toISOString(),
  };
  const normalized = normalizeDesignSample(prepareDesignSampleForSave(merged));
  const nextSamples = library.samples.slice();
  nextSamples[index] = normalized;
  return {
    sample: normalized,
    library: writeDesignSamples(nextSamples),
  };
}

function cleanupGoldenSampleFiles(sample = {}) {
  const screenshotPath = sample.renderEvidence?.screenshotPath || "";
  if (!screenshotPath) return;
  const absolutePath = path.resolve(mutableStoragePath(screenshotPath));
  if (!canAccessMutablePath(absolutePath, GOLDEN_SAMPLE_ASSET_DIR) || !fs.existsSync(absolutePath)) return;
  try {
    fs.unlinkSync(absolutePath);
  } catch (error) {
    // Best-effort cleanup: deleting metadata is more important than blocking on a stale file.
  }
}

function deleteDesignSample(id, options = {}) {
  const library = readDesignSamples();
  const normalizedId = safeId(id, "design-sample");
  const existing = library.samples.find((sample) => sample.id === normalizedId);
  if (!existing) {
    throw Object.assign(new Error("Design sample not found"), { statusCode: 404 });
  }
  if (options.cleanupAssets) cleanupGoldenSampleFiles(existing);
  const libraryAfterDelete = writeDesignSamples(library.samples.filter((sample) => sample.id !== normalizedId));
  return {
    deleted: existing,
    library: libraryAfterDelete,
  };
}

function designSampleSearchText(sample) {
  if (sample && typeof sample === "object" && sample.__searchText) return sample.__searchText;
  const text = normalizeKeywordText(
    [
      sample.id,
      sample.name,
      sample.scenario,
      sample.pageIntent,
      sample.visualStyle,
      sample.prompt,
      sample.whyGood,
      sample.whyBad,
      sample.forbiddenReuse,
      ...(Array.isArray(sample.tags) ? sample.tags : []),
      ...(Array.isArray(sample.scenarioTags) ? sample.scenarioTags : []),
      ...(Array.isArray(sample.applicableScenarios) ? sample.applicableScenarios : []),
      sample.page?.layout,
      sample.page?.hero,
      sample.configSnapshot?.layoutPreset,
      sample.configSnapshot?.themePreset,
      sample.configSnapshot?.mainVisual,
      ...(Array.isArray(sample.configSnapshot?.brickIds) ? sample.configSnapshot.brickIds : []),
      ...(Array.isArray(sample.functions) ? sample.functions.flatMap((item) => [item.name, item.objective, ...(item.modules || []), ...(item.actions || [])]) : []),
      ...(Array.isArray(sample.sampleBlocks) ? sample.sampleBlocks.flatMap((item) => [item.name, item.page, item.function, ...(item.visualNotes || [])]) : []),
      ...(Array.isArray(sample.goodPatterns) ? sample.goodPatterns : []),
      ...(Array.isArray(sample.avoidPatterns) ? sample.avoidPatterns : []),
    ].join(" "),
  );
  if (sample && typeof sample === "object") {
    Object.defineProperty(sample, "__searchText", {
      value: text,
      enumerable: false,
      configurable: true,
    });
  }
  return text;
}

function designSampleRankScore(sample, prompt, index = 0, options = {}) {
  const text = normalizeKeywordText(prompt);
  const words = text.split(/\s+|[，,。；;、]/).filter((word) => word.length >= 2);
  const haystack = designSampleSearchText(sample);
  const promptHits = words.filter((word) => haystack.includes(word)).length;
  const tagHits = [...(sample.tags || []), ...(sample.scenarioTags || []), ...(sample.applicableScenarios || [])].filter((tag) => text.includes(String(tag).toLowerCase()) || text.includes(String(tag))).length;
  const score = Number.isFinite(Number(sample.humanScore)) ? sample.humanScore : sample.aestheticScore || 0;
  const goldenBoost = sample.isGolden ? 90 : 0;
  const antiBoost = options.antiExamples ? 30 : sample.isAntiExample ? -200 : 0;
  const evidenceBoost = sample.renderEvidence?.domSnapshot || sample.renderEvidence?.screenshotPath || sample.renderEvidence?.screenshotUrl || sample.renderEvidence?.sourceUrl || sample.referenceAssetId || sample.homepageConfig ? 12 : 0;
  const dimensionBoost = Object.keys(sample.scoreDimensions || {}).length >= 4 ? 8 : 0;
  return promptHits * 8 + tagHits * 16 + Math.round(score / 8) + goldenBoost + antiBoost + evidenceBoost + dimensionBoost - index * 0.01;
}

function rankDesignSamplesForPrompt(prompt, limit = 4, options = {}) {
  const includeAntiExamples = Boolean(options.includeAntiExamples);
  const cacheKey = JSON.stringify(["all", normalizeKeywordText(prompt).slice(0, 500), Math.max(1, Math.min(Number(limit) || 4, 8)), includeAntiExamples, Boolean(options.antiExamples)]);
  if (designSampleRankCache.has(cacheKey)) return designSampleRankCache.get(cacheKey).slice();
  const ranked = readDesignSamples().samples
    .filter((sample) => includeAntiExamples || !sample.isAntiExample)
    .map((sample, index) => {
      return {
        sample,
        score: designSampleRankScore(sample, prompt, index, options),
      };
    })
    .sort((a, b) => b.score - a.score)
    .map((item) => item.sample)
    .slice(0, Math.max(1, Math.min(Number(limit) || 4, 8)));
  designSampleRankCache.set(cacheKey, ranked);
  return ranked.slice();
}

function rankGoldenDesignSamplesForPrompt(prompt, limit = 3) {
  const cacheKey = JSON.stringify(["golden", normalizeKeywordText(prompt).slice(0, 500), Math.max(1, Math.min(Number(limit) || 3, 5))]);
  if (designSampleRankCache.has(cacheKey)) return designSampleRankCache.get(cacheKey).slice();
  const samples = readDesignSamples().samples.filter((sample) => sample.isGolden && !sample.isAntiExample);
  const ranked = samples
    .map((sample, index) => ({ sample, score: designSampleRankScore(sample, prompt, index) }))
    .sort((a, b) => b.score - a.score)
    .map((item) => item.sample)
    .slice(0, Math.max(1, Math.min(Number(limit) || 3, 5)));
  designSampleRankCache.set(cacheKey, ranked);
  return ranked.slice();
}

function rankLowScoreAntiExamplesForPrompt(prompt, limit = 3) {
  const cacheKey = JSON.stringify(["anti", normalizeKeywordText(prompt).slice(0, 500), Math.max(1, Math.min(Number(limit) || 3, 5))]);
  if (designSampleRankCache.has(cacheKey)) return designSampleRankCache.get(cacheKey).slice();
  const samples = readDesignSamples().samples.filter((sample) => sample.isAntiExample || Number(sample.humanScore ?? sample.aestheticScore) <= 68);
  const ranked = samples
    .map((sample, index) => ({ sample, score: designSampleRankScore(sample, prompt, index, { antiExamples: true }) }))
    .sort((a, b) => b.score - a.score)
    .map((item) => item.sample)
    .slice(0, Math.max(1, Math.min(Number(limit) || 3, 5)));
  designSampleRankCache.set(cacheKey, ranked);
  return ranked.slice();
}

function limitedObjectEntries(value = {}, limit = 18, textLimit = 120) {
  return Object.fromEntries(
    Object.entries(value && typeof value === "object" && !Array.isArray(value) ? value : {})
      .slice(0, limit)
      .map(([key, item]) => [cleanText(key, "", 80), cleanText(item, "", textLimit)])
      .filter(([key, item]) => key && item),
  );
}

function summarizeGoldenLayoutTokens(tokens = {}) {
  const source = tokens && typeof tokens === "object" && !Array.isArray(tokens) ? tokens : {};
  return {
    maxWidths: cssSummaryList(source.maxWidths).slice(0, 8),
    heights: cssSummaryList(source.heights).slice(0, 6),
    gridTemplates: cssSummaryList(source.gridTemplates).slice(0, 8),
    gapScale: cssSummaryList(source.gapScale).slice(0, 8),
    paddingScale: cssSummaryList(source.paddingScale).slice(0, 8),
    marginScale: cssSummaryList(source.marginScale).slice(0, 6),
    breakpoints: cssSummaryList(source.breakpoints).slice(0, 6),
    sectionCount: Number(source.sectionCount) || 0,
    hierarchyDepth: Number(source.hierarchyDepth) || 0,
    hasNavigation: Boolean(source.hasNavigation),
  };
}

function summarizeGoldenComponentCard(card = {}) {
  return {
    id: cleanText(card.id, "", 80),
    role: cleanText(card.role, "", 60),
    heading: cleanText(card.heading, "", 80),
    classNames: (Array.isArray(card.classNames) ? card.classNames : []).map((item) => cleanText(item, "", 60)).filter(Boolean).slice(0, 8),
    dataHooks: (Array.isArray(card.dataHooks) ? card.dataHooks : []).map((item) => cleanText(item, "", 80)).filter(Boolean).slice(0, 6),
    metrics: (Array.isArray(card.metrics) ? card.metrics : []).map((item) => cleanText(item, "", 40)).filter(Boolean).slice(0, 8),
    visibleText: cleanText(card.visibleText, "", 160),
    styleRules: (Array.isArray(card.styleRules) ? card.styleRules : []).map((item) => cleanText(item, "", 220)).filter(Boolean).slice(0, 3),
  };
}

function summarizeGoldenEvidence(cssSummary = {}, themeTokens = {}) {
  const css = cssSummary && typeof cssSummary === "object" ? cssSummary : {};
  const tokens = themeTokens && typeof themeTokens === "object" ? themeTokens : {};
  const layoutTokens = summarizeGoldenLayoutTokens({
    ...(tokens.layoutTokens || {}),
    ...(css.layoutTokens || {}),
  });
  const componentCards = (Array.isArray(css.componentCards) && css.componentCards.length ? css.componentCards : tokens.componentCards || [])
    .slice(0, 8)
    .map(summarizeGoldenComponentCard);
  return {
    colorPalette: mergeGoldenTokenArrays(css.colorPalette, tokens.colorPalette, 16),
    spacingScale: mergeGoldenTokenArrays(css.spacingScale, tokens.spacingScale, 16),
    radiusScale: mergeGoldenTokenArrays(css.radiusScale, tokens.radiusScale, 10),
    shadowStyle: mergeGoldenTokenArrays(css.shadowStyle, tokens.shadowStyle, 8),
    fontScale: mergeGoldenTokenArrays(css.fontScale, tokens.fontScale, 10),
    cssVariables: {
      ...limitedObjectEntries(css.cssVariables, 16, 120),
      ...limitedObjectEntries(tokens.cssVariables, 16, 120),
    },
    layoutTokens,
    componentCards,
    layoutSignals: mergeGoldenTokenArrays(css.layoutSignals, tokens.layoutSignals, 10),
    componentStyleNotes: mergeGoldenTokenArrays(css.componentStyleNotes, tokens.componentStyleNotes, 10),
    sourceFiles: (Array.isArray(css.sourceFiles) ? css.sourceFiles : []).map((item) => cleanText(item, "", 120)).filter(Boolean).slice(0, 6),
    sourceExtractionStatus: cleanText(css.sourceExtractionStatus, "", 40),
  };
}

function summarizeDesignSampleForPrompt(sample) {
  const evidence = sample.renderEvidence || {};
  const cssSummary = evidence.cssSummary || {};
  const themeTokens = evidence.themeTokens || {};
  return {
    id: sample.id,
    sampleKind: sample.sampleKind,
    sourceType: sample.sourceType,
    visualOnly: Boolean(sample.visualOnly),
    isGolden: Boolean(sample.isGolden),
    isAntiExample: Boolean(sample.isAntiExample),
    name: sample.name,
    scenario: sample.scenario,
    pageIntent: sample.pageIntent,
    themePreset: sample.themePreset,
    visualStyle: sample.visualStyle,
    prompt: cleanText(sample.prompt, "", 320),
    aestheticScore: sample.aestheticScore,
    humanScore: sample.humanScore,
    scenarioTags: sample.scenarioTags,
    scoreDimensions: sample.scoreDimensions,
    page: sample.page,
    functions: sample.functions.slice(0, 5),
    sampleBlocks: sample.sampleBlocks.slice(0, 6),
    componentRefs: sample.componentRefs.slice(0, 8),
    goodPatterns: sample.goodPatterns.slice(0, 8),
    avoidPatterns: sample.avoidPatterns.slice(0, 6),
    whyGood: cleanText(sample.whyGood, "", 320),
    whyBad: cleanText(sample.whyBad, "", 320),
    applicableScenarios: sample.applicableScenarios.slice(0, 6),
    forbiddenReuse: cleanText(sample.forbiddenReuse, "", 260),
    evidence: {
      screenshotPath: evidence.screenshotPath || "",
      screenshotUrl: evidence.screenshotUrl || "",
      sourceUrl: evidence.sourceUrl || "",
      hasDomSnapshot: Boolean(evidence.domSnapshot),
      hasAiHtml: Boolean(evidence.aiHtml),
      goldenTokens: summarizeGoldenEvidence(cssSummary, themeTokens),
      configSnapshot: sample.configSnapshot || null,
      configSnapshotStatus: sample.configSnapshot ? "available" : sample.visualOnly ? "empty-visual-reference-only" : "empty",
    },
  };
}

