async function callProviderWithPrompt(payload, promptParts, schema, schemaName = "ai_output") {
  const config = normalizeProviderConfig(payload.modelConfig);

  const apiKey = resolveApiKey(config);
  if (!apiKey) {
    const expected = config.keyEnv.join(" or ");
    throw Object.assign(new Error(`Missing API key. Set ${expected} or enter a temporary key in the UI.`), { statusCode: 400 });
  }

  return requestAndParseProviderJson(config, apiKey, promptParts, schema || payload.context?.schema, schemaName);
}

function geminiJsonFailureShouldFallback(config = {}, error = {}) {
  if (!canFallbackGeminiModel(config)) return false;
  const details = error.details || {};
  const finishReason = String(details.finishReason || "");
  const message = `${error.message || ""} ${finishReason} ${details.rawTextSnippet || ""}`;
  return Boolean(details.likelyTruncated) || /valid JSON object|Provider returned an empty|length|max_tokens|content_filter/i.test(message);
}

// 结构化输出的降级链（根因 B）：可靠性递减 json_schema → tool → json_object → text。
// 按供应商/接口能力给出"优先尝试 + 逐级降级"顺序；无 schema 或显式 text 时只跑纯文本。
function structuredModesForConfig(config, schema) {
  if (config.responseFormat === "text" || !schema || typeof schema !== "object") return ["text"];
  if (config.apiMode === "responses") return ["json_schema", "text"];
  if (config.apiMode === "anthropic-messages") return ["tool", "text"]; // Anthropic 唯一结构化手段是 tool use
  if (config.provider === "minimax") return ["json_object", "text"]; // MiniMax 仅可靠支持 json_object
  return ["json_schema", "tool", "json_object", "text"]; // gemini/kimi/deepseek
}

// 错误是否表示"当前结构化模式不被支持/参数非法"，可降级到下一档重试（而非真正的业务/网络错误）。
function structuredModeRejected(error) {
  const status = Number(error?.providerStatus || error?.details?.providerStatus);
  if (status && ![400, 404, 415, 422].includes(status)) return false;
  return /response_format|json_schema|json mode|json_object|tool|function|schema|unsupported|not support|not supported|invalid parameter|invalid param|invalid_request|不支持|无效|非法|参数/i.test(
    String(error?.message || ""),
  );
}

async function requestProviderJsonWithStructuredFallback(config, apiKey, promptParts, schema, schemaName) {
  const modes = structuredModesForConfig(config, schema);
  let lastError = null;
  for (let index = 0; index < modes.length; index += 1) {
    const mode = modes[index];
    const { headers, body } = buildProviderRequest(config, apiKey, promptParts, schema, schemaName, mode);
    try {
      const result = await requestProviderJson(config, headers, body);
      if (index > 0) {
        result.attempts = [
          ...(lastError?.details?.attempts || []),
          {
            provider: config.provider,
            providerName: config.name,
            model: config.model,
            apiMode: config.apiMode,
            message: `结构化模式 ${modes[index - 1]} 失败，已降级为 ${mode}。`,
          },
          ...(result.attempts || []),
        ];
      }
      return result;
    } catch (error) {
      lastError = error;
      if (index < modes.length - 1 && structuredModeRejected(error)) continue;
      throw error;
    }
  }
  throw lastError;
}

async function requestAndParseProviderJson(config, apiKey, promptParts, schema, schemaName = "ai_output", previousError = null) {
  let providerResult;
  try {
    providerResult = await requestProviderJsonWithStructuredFallback(config, apiKey, promptParts, schema, schemaName);
  } catch (error) {
    throw error.details ? error : enrichProviderError(error, config, null);
  }
  const usedConfig = providerResult.config;
  const rawText = extractTextFromAiResponse(providerResult.response, usedConfig.apiMode);
  const finishReason = extractProviderFinishReason(providerResult.response);
  let json;
  try {
    json = extractJsonObject(rawText);
  } catch (error) {
    const stripped = stripReasoningText(rawText);
    const looksTruncated = stripped.trim().startsWith("{") && stripped.lastIndexOf("}") <= stripped.indexOf("{");
    const enriched = enrichProviderError(error, usedConfig, providerResult.target, {
      rawTextSnippet: stripReasoningText(rawText).slice(0, 500),
      finishReason: finishReason || null,
      likelyTruncated: looksTruncated || /length|max_tokens|content_filter/i.test(finishReason || ""),
      attempts: providerResult.attempts,
      previousAttempt: previousError?.details || null,
    });
    // If the model ran out of output budget mid-JSON, retry the SAME model with a higher
    // token ceiling before degrading to a weaker model or the brick fallback. Truncation is a
    // budget problem, not a model-capability problem, so a downgrade would only lose quality.
    if (enriched.details?.likelyTruncated && !usedConfig.tokenBumped) {
      const ceiling = providerMaxOutputCeiling(usedConfig.provider);
      if (ceiling > (usedConfig.maxOutputTokens || 0)) {
        const retryConfig = { ...usedConfig, maxOutputTokens: ceiling, tokenBumped: true };
        return requestAndParseProviderJson(retryConfig, apiKey, promptParts, schema, schemaName, enriched);
      }
    }
    if (usedConfig.provider === "deepseek" && usedConfig.model === DEEPSEEK_PRO_MODEL) {
      const retryConfig = { ...usedConfig, model: DEEPSEEK_FLASH_MODEL, fallbackFromModel: DEEPSEEK_PRO_MODEL };
      return requestAndParseProviderJson(retryConfig, apiKey, promptParts, schema, schemaName, enriched);
    }
    if (geminiJsonFailureShouldFallback(usedConfig, enriched)) {
      const retryConfig = { ...usedConfig, model: GEMINI_DEFAULT_MODEL, fallbackFromModel: usedConfig.model };
      return requestAndParseProviderJson(retryConfig, apiKey, promptParts, schema, schemaName, enriched);
    }
    throw enriched;
  }

  return {
    json,
    provider: usedConfig.provider,
    model: usedConfig.model,
    rawText,
    usage: providerResult.response.usage || null,
  };
}

async function testProviderConnection(payload) {
  const config = normalizeProviderConfig(payload.modelConfig);
  const apiKey = resolveApiKey(config);

  if (!apiKey) {
    const expected = config.keyEnv.join(" or ");
    throw Object.assign(new Error(`Missing API key. Set ${expected} or enter a temporary key in the UI.`), { statusCode: 400 });
  }

  const startedAt = Date.now();
  const promptParts = {
    system: "You are a provider connectivity test. Reply with only OK.",
    user: "Reply with only OK. This request only checks whether the configured model endpoint is reachable.",
  };
  const testConfig = { ...config, maxOutputTokens: Math.min(config.maxOutputTokens, 512), responseFormat: "text" };
  const { headers, body } = buildProviderRequest(testConfig, apiKey, promptParts, null, "connectivity_test");

  let providerResult;
  try {
    providerResult = await requestProviderJson(testConfig, headers, body);
  } catch (error) {
    throw error.details ? error : enrichProviderError(error, testConfig, null);
  }

  const usedConfig = providerResult.config;
  const rawText = extractTextFromAiResponse(providerResult.response, usedConfig.apiMode);
  return {
    provider: usedConfig.provider,
    providerName: usedConfig.name,
    model: usedConfig.model,
    apiMode: usedConfig.apiMode,
    baseUrl: usedConfig.baseUrl,
    endpoint: usedConfig.endpoint,
    url: `${providerResult.target.origin}${providerResult.target.pathname}`,
    durationMs: Date.now() - startedAt,
    message: stripReasoningText(rawText).slice(0, 220) || "Provider returned an empty but successful response.",
    attempts: providerResult.attempts,
    usage: providerResult.response.usage || null,
  };
}

