async function callAuthProvider(payload = {}) {
  const config = normalizeProviderConfig(payload.modelConfig || {});
  const apiKey = resolveApiKey(config);
  const fallback = (reason, mock = false) => ({
    scheme: normalizeAuthScheme(null, payload, config, {
      sourceType: reason ? "local-fallback" : "local",
      mock,
      isFallback: Boolean(reason),
      fallbackReason: reason,
    }),
    provider: config.provider,
    model: config.model,
    rawText: "",
    mock,
    localFallback: Boolean(reason),
    fallbackReason: reason,
  });

  if (process.env.AUTH_AI_MOCK === "true" || process.env.HOME_AI_MOCK === "true") {
    return fallback("AUTH_AI_MOCK/HOME_AI_MOCK 已启用，使用本地认证界面草稿。", true);
  }

  if (!apiKey) {
    return fallback(`Missing API key. Set ${config.keyEnv.join(" or ")} or enter a temporary key in the UI.`, true);
  }

  try {
    const result = await requestAndParseProviderJson(config, apiKey, buildAuthPrompt(payload, config), AUTH_UI_JSON_SCHEMA, "auth_ui_scheme");
    return {
      scheme: normalizeAuthScheme(result.json, payload, { ...config, provider: result.provider, model: result.model }, { sourceType: "model" }),
      provider: result.provider,
      model: result.model,
      rawText: result.rawText,
      usage: result.usage,
    };
  } catch (error) {
    const reason = cleanText(providerFailureSummary(error), "认证界面 AI 生成失败，已使用本地安全草稿。", 220);
    return fallback(reason, false);
  }
}

function authRecordSnapshot(scheme = {}) {
  return {
    name: safeRecordText(scheme.name, 80),
    stylePreset: safeRecordText(scheme.stylePreset, 40),
    defaultScreen: safeRecordText(scheme.defaultScreen, 40),
    language: safeRecordText(scheme.language, 20),
    brand: safeRecordText(scheme.brand?.name, 40),
    sourceType: safeRecordText(scheme.sourceType, 40),
    fallbackReason: safeRecordText(scheme.fallbackReason, 180),
    audience: safeRecordText(scheme.experience?.audience, 40),
    registerDepth: safeRecordText(scheme.experience?.registerDepth, 40),
    screens: AUTH_SCREEN_KEYS.filter((key) => Boolean(scheme.screens?.[key])),
  };
}

async function runAuthGenerate(payload, startedAt = Date.now()) {
  let historyConfig = null;
  let failedCallRecord = null;

  try {
    historyConfig = callHistoryConfig(payload);
    const result = await callAuthProvider(payload);
    const status = result.localFallback ? "fallback" : result.mock ? "mock" : "success";
    const callRecord = addAuthCallHistoryRecord({
      action: "auth-generate",
      providerId: result.provider || historyConfig.provider,
      provider: historyConfig.name,
      model: result.model || historyConfig.model,
      apiMode: historyConfig.apiMode,
      callMode: "serverProxy",
      baseUrl: historyConfig.baseUrl,
      endpoint: historyConfig.endpoint,
      temperature: historyConfig.temperature,
      maxOutputTokens: historyConfig.maxOutputTokens,
      status,
      mock: Boolean(result.mock),
      durationMs: Date.now() - startedAt,
      prompt: safeRecordText(payload.prompt),
      message: result.scheme?.name || result.fallbackReason || "登录注册界面生成成功",
      schemeSnapshot: authRecordSnapshot(result.scheme),
      usage: result.usage || null,
    });
    return { ok: true, ...result, callRecord };
  } catch (error) {
    if (payload) {
      const config = historyConfig || callHistoryConfig(payload);
      failedCallRecord = addAuthCallHistoryRecord({
        action: "auth-generate",
        providerId: config.provider,
        provider: config.name,
        model: config.model,
        apiMode: config.apiMode,
        callMode: "serverProxy",
        baseUrl: config.baseUrl,
        endpoint: config.endpoint,
        temperature: config.temperature,
        maxOutputTokens: config.maxOutputTokens,
        status: "failed",
        durationMs: Date.now() - startedAt,
        prompt: safeRecordText(payload.prompt),
        message: safeRecordText(error.message || "Auth UI generation failed", 900),
      });
    }
    const status = error.statusCode && error.statusCode >= 400 && error.statusCode < 600 ? error.statusCode : 500;
    const wrapped = new Error(error.message || "Auth UI generation failed");
    wrapped.statusCode = status;
    wrapped.details = error.details || null;
    wrapped.callRecord = failedCallRecord;
    throw wrapped;
  }
}

async function handleAuthGenerate(req, res) {
  try {
    const payload = await readJsonBody(req);
    sendJson(res, 200, await runAuthGenerate(payload));
  } catch (error) {
    const status = error.statusCode && error.statusCode >= 400 && error.statusCode < 600 ? error.statusCode : 500;
    sendJson(res, status, {
      ok: false,
      error: error.message || "Auth UI generation failed",
      details: error.details || null,
      callRecord: error.callRecord || null,
    });
  }
}

async function handleAuthTest(req, res) {
  const startedAt = Date.now();
  let payload = null;
  let historyConfig = null;
  let failedCallRecord = null;

  try {
    payload = await readJsonBody(req);
    historyConfig = callHistoryConfig(payload);
    const result = await testProviderConnection(payload);
    const callRecord = addAuthCallHistoryRecord({
      action: "connectivity-test",
      providerId: result.provider || historyConfig.provider,
      provider: result.providerName || historyConfig.name,
      model: result.model || historyConfig.model,
      apiMode: result.apiMode || historyConfig.apiMode,
      callMode: "serverProxy",
      baseUrl: result.baseUrl || historyConfig.baseUrl,
      endpoint: result.endpoint || historyConfig.endpoint,
      temperature: historyConfig.temperature,
      maxOutputTokens: historyConfig.maxOutputTokens,
      status: "success",
      durationMs: result.durationMs || Date.now() - startedAt,
      prompt: "认证模块连通性测试",
      message: result.message || result.url || "连通成功",
      usage: result.usage || null,
    });
    sendJson(res, 200, { ok: true, ...result, callRecord });
  } catch (error) {
    if (payload) {
      const config = historyConfig || callHistoryConfig(payload);
      failedCallRecord = addAuthCallHistoryRecord({
        action: "connectivity-test",
        providerId: config.provider,
        provider: config.name,
        model: config.model,
        apiMode: config.apiMode,
        callMode: "serverProxy",
        baseUrl: config.baseUrl,
        endpoint: config.endpoint,
        temperature: config.temperature,
        maxOutputTokens: config.maxOutputTokens,
        status: "failed",
        durationMs: Date.now() - startedAt,
        prompt: "认证模块连通性测试",
        message: safeRecordText(error.message || "AI provider test failed", 900),
      });
    }
    const status = error.statusCode && error.statusCode >= 400 && error.statusCode < 600 ? error.statusCode : 500;
    sendJson(res, status, {
      ok: false,
      error: error.message || "AI provider test failed",
      details: error.details || null,
      callRecord: failedCallRecord,
    });
  }
}

async function callProvider(payload) {
  const config = normalizeProviderConfig(payload.modelConfig);
  const modulePolicy = buildHomepageModulePolicy(payload);
  const policyPayload = { ...payload, modulePolicy };
  const renderMode = homepageRenderMode(payload);
  const compactAiHtmlProvider = providerUsesCompactAiHtml(config);

  if (process.env.HOME_AI_MOCK === "true") {
    const rawMockConfig = enforceHomepagePromptIntent(policyPayload, mockHomepageConfig(policyPayload, config));
    const guidedSnapshot = homepageGuidedSnapshotFromPayload(policyPayload, rawMockConfig);
    const repaired = repairHomepageConfig(rawMockConfig, guidedSnapshot, modulePolicy, payload.prompt);
    const mockConfig = applyHomepagePagePlan(repaired.config, policyPayload, repaired.repairActions);
    const pagePlanPolicyRepair = applyHomepageModulePolicy(mockConfig, modulePolicy, repaired.repairActions);
    applyComponentReferencesToHomepageConfig(mockConfig, policyPayload.prompt, { actions: repaired.repairActions });
    applyGoldenStyleContractToHomepageConfig(mockConfig, policyPayload.prompt, repaired.repairActions);
    enforceFourColumnTradingAccountContract(mockConfig, policyPayload.prompt);
    ensureLargeHomepageBrickPlanSections(mockConfig);
    applyGoldenStyleContractToHomepageConfig(mockConfig, policyPayload.prompt, repaired.repairActions);
    applySectionTransitionsToHomepageConfig(mockConfig, repaired.repairActions);
    const combinedPolicyRepair = mergeHomepageModulePolicyRepairResults(repaired.modulePolicyRepairResult, pagePlanPolicyRepair);
    repaired.config = mockConfig;
    repaired.validation = validateHomepageConfig(mockConfig, guidedSnapshot, modulePolicy, combinedPolicyRepair);
    mockConfig.validation = repaired.validation;
    mockConfig.validationWarnings = repaired.validation.warnings || [];
    mockConfig.modulePolicy = modulePolicy;
    mockConfig.modulePolicyScore = repaired.validation.modulePolicy?.score ?? 100;
    let htmlScheme = renderModeWantsAiHtml(renderMode) ? mockAiHtmlScheme(policyPayload, mockConfig, config) : null;
    // 两阶段开关：renderMode=skeletonHtml 时用骨架+逐槽生成（mock 路径确定性），失败回退上面的 mock 整页方案。
    if (twoStageHomepageEnabled() && renderMode === "skeletonHtml") {
      try {
        htmlScheme = await orchestrateTwoStageHomepage(policyPayload, mockConfig, config, { mock: true });
        mockConfig.skeletonHtmlScheme = htmlScheme; // 走既有 skeletonHtmlScheme 渲染路径
      } catch (error) {
        console.warn("[two-stage] mock 编排失败，回退 mockAiHtmlScheme:", error && error.message);
      }
    }
    const finalQuality = finalizeHomepageQuality(policyPayload, mockConfig, htmlScheme);
    const finalConfig = {
      ...mockConfig,
      validation: repaired.validation,
      validationWarnings: repaired.validation.warnings || [],
      modulePolicy,
      modulePolicyScore: finalQuality.modulePolicyScore,
      repairActions: repaired.repairActions,
      qualityScore: finalQuality.score,
      quality: finalQuality.quality,
      htmlQualityStatus: finalQuality.htmlQualityStatus,
      productWarnings: finalQuality.productWarnings,
    };
    return {
      config: {
        ...finalConfig,
        renderMode,
        htmlGenerationEnabled: renderModeWantsAiHtml(renderMode),
        skeletonHtmlEnabled: renderMode === "skeletonHtml",
        activeRenderMode: activeRenderModeForRequest(renderMode, htmlScheme),
        ...(htmlScheme ? { htmlScheme } : {}),
      },
      ...(htmlScheme ? { htmlScheme } : {}),
      validation: repaired.validation,
      validationWarnings: repaired.validation.warnings || [],
      modulePolicy,
      modulePolicyScore: finalQuality.modulePolicyScore,
      repairActions: repaired.repairActions,
      qualityScore: finalQuality.score,
      quality: finalQuality.quality,
      htmlQualityStatus: finalQuality.htmlQualityStatus,
      productWarnings: finalQuality.productWarnings,
      renderMode,
      activeRenderMode: activeRenderModeForRequest(renderMode, htmlScheme),
	      provider: config.provider,
	      model: config.model,
	      rawText: "",
	      responseJson: {
	        homepageConfig: safeRecordJsonValue(rawMockConfig, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	        normalizedConfig: safeRecordJsonValue(finalConfig, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	        aiHtml: htmlScheme ? safeRecordJsonValue(htmlScheme, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }) : null,
	      },
	      mock: true,
	    };
	  }

  // 提速 B：自由 HTML 与配置两次调用互不依赖，并发发起（在任何 await 之前创建 Promise），省掉一次调用的墙钟时间。
  let freeHtmlResult = null;
  let freeHtmlError = null;
  let freeHtmlPromise = null;
  if (renderModeWantsAiHtml(renderMode)) {
    if (compactAiHtmlProvider) {
      freeHtmlError = new Error(`${config.name} 使用短输出 AI HTML 通道，跳过长自由 HTML 首轮。`);
    } else {
      freeHtmlPromise = callProviderWithPrompt(
        { ...policyPayload, modelConfig: { ...(policyPayload.modelConfig || {}), aiHtmlAttempt: true } },
        aiHtmlPromptForProvider(config, policyPayload, {}, { free: true }),
        AI_HTML_SCHEME_JSON_SCHEMA,
        "homepage_ai_html_free",
      ).catch((error) => {
        freeHtmlError = error;
        return null;
      });
    }
  }

  const configPromise = callProviderWithPrompt(policyPayload, buildPrompt(policyPayload, config), policyPayload.context?.schema || HOMEPAGE_CONFIG_SCHEMA, "homepage_config");
  if (freeHtmlPromise) freeHtmlResult = await freeHtmlPromise;
  const result = await configPromise;
  const rawHomepageConfig = enforceHomepagePromptIntent(
    policyPayload,
    prepareProviderHomepageConfig(policyPayload, result.json, { ...config, provider: result.provider, model: result.model }),
  );
  const guidedSnapshot = homepageGuidedSnapshotFromPayload(policyPayload, rawHomepageConfig);
  const repaired = repairHomepageConfig(rawHomepageConfig, guidedSnapshot, modulePolicy, payload.prompt);
  const homepageConfig = applyHomepagePagePlan(repaired.config, policyPayload, repaired.repairActions);
  const pagePlanPolicyRepair = applyHomepageModulePolicy(homepageConfig, modulePolicy, repaired.repairActions);
  applyComponentReferencesToHomepageConfig(homepageConfig, policyPayload.prompt, { actions: repaired.repairActions });
  applyGoldenStyleContractToHomepageConfig(homepageConfig, policyPayload.prompt, repaired.repairActions);
  enforceFourColumnTradingAccountContract(homepageConfig, policyPayload.prompt);
  ensureLargeHomepageBrickPlanSections(homepageConfig);
  applyGoldenStyleContractToHomepageConfig(homepageConfig, policyPayload.prompt, repaired.repairActions);
  applySectionTransitionsToHomepageConfig(homepageConfig, repaired.repairActions);
  const combinedPolicyRepair = mergeHomepageModulePolicyRepairResults(repaired.modulePolicyRepairResult, pagePlanPolicyRepair);
  repaired.config = homepageConfig;
  repaired.validation = validateHomepageConfig(homepageConfig, guidedSnapshot, modulePolicy, combinedPolicyRepair);
  homepageConfig.validation = repaired.validation;
  homepageConfig.validationWarnings = repaired.validation.warnings || [];
  homepageConfig.modulePolicy = modulePolicy;
  homepageConfig.modulePolicyScore = repaired.validation.modulePolicy?.score ?? 100;
  const resultProviderConfig = { ...config, provider: result.provider, model: result.model };
  const htmlPayload = {
    ...policyPayload,
    modelConfig: {
      ...(payload.modelConfig || {}),
      provider: resultProviderConfig.provider,
      model: resultProviderConfig.model,
      apiMode: resultProviderConfig.apiMode,
      baseUrl: resultProviderConfig.baseUrl,
      endpoint: resultProviderConfig.endpoint,
    },
  };
	  let htmlScheme = null;
	  let htmlUsage = null;
	  let htmlRawText = "";
	  let htmlResponseJson = null;

	  // 两阶段开关：renderMode=skeletonHtml 时优先走骨架+逐槽并发生成；失败则回退到下方自由 HTML 通道。
	  if (twoStageHomepageEnabled() && renderMode === "skeletonHtml") {
	    try {
	      htmlScheme = await orchestrateTwoStageHomepage(policyPayload, homepageConfig, resultProviderConfig, { mock: false });
	      homepageConfig.skeletonHtmlScheme = htmlScheme; // 走既有 skeletonHtmlScheme 渲染路径
	    } catch (error) {
	      console.warn("[two-stage] 编排失败，回退自由 HTML 通道:", error && error.message);
	    }
	  }

	  if (renderModeWantsAiHtml(renderMode) && !htmlScheme) {
	    if (freeHtmlResult?.json) {
      htmlScheme = repairAiHtmlScheme(freeHtmlResult.json, policyPayload, homepageConfig, resultProviderConfig, {
        sourceType: "model/free-html",
	        generationPipeline: "free-html-first",
	        modelAttempted: true,
	        mock: false,
	      });
	      htmlUsage = freeHtmlResult.usage || null;
	      htmlRawText = freeHtmlResult.rawText || "";
	      htmlResponseJson = safeRecordJsonValue(freeHtmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 });
	      if (htmlScheme.qualityStatus !== "passed" && resultProviderConfig.provider !== "minimax") {
        const qualityReport = evaluateAiHtmlQuality(htmlScheme, policyPayload, homepageConfig);
	        try {
	          const htmlResult = await callProviderWithPrompt(
	            htmlPayload,
	            aiHtmlPromptForProvider(resultProviderConfig, policyPayload, homepageConfig, { qualityReport, previousScheme: htmlScheme }),
	            AI_HTML_SCHEME_JSON_SCHEMA,
	            "homepage_ai_html_quality_repair",
			          );
	          const previousHtmlScheme = htmlScheme;
	          htmlResponseJson = {
	            free: safeRecordJsonValue(freeHtmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	            repair: safeRecordJsonValue(htmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	          };
	          const repairedHtmlScheme = repairAiHtmlScheme(
            {
              ...htmlResult.json,
              correctionNotes: [
                `自由 HTML 质量门禁 ${qualityReport.score}/100，已根据问题自动返修。`,
                ...(Array.isArray(qualityReport.issues) ? qualityReport.issues : []),
                ...(Array.isArray(htmlResult.json?.correctionNotes) ? htmlResult.json.correctionNotes : []),
              ],
            },
	            policyPayload,
	            homepageConfig,
	            resultProviderConfig,
		            { sourceType: "model-repair", generationPipeline: "free-html-quality-gate", modelAttempted: true, mock: false },
		          );
          const previousScore = Number(previousHtmlScheme.qualityScore);
          const repairedScore = Number(repairedHtmlScheme.qualityScore);
          if (Number.isFinite(previousScore) && Number.isFinite(repairedScore) && repairedScore < previousScore) {
            htmlScheme = {
              ...previousHtmlScheme,
              correctionNotes: [
                ...(Array.isArray(previousHtmlScheme.correctionNotes) ? previousHtmlScheme.correctionNotes : []),
                `质量返修得分 ${repairedScore}/100 低于自由版 ${previousScore}/100，已保留自由 HTML 方案。`,
              ].slice(0, 8),
              generationPipeline: "free-html-quality-gate",
            };
          } else {
            htmlScheme = repairedHtmlScheme;
          }
          htmlUsage = { free: freeHtmlResult.usage || null, repair: htmlResult.usage || null };
          htmlRawText = [freeHtmlResult.rawText, htmlResult.rawText].filter(Boolean).join("\n\n--- ai html quality repair ---\n\n");
	        } catch (error) {
	          htmlResponseJson = safeRecordJsonValue(freeHtmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 });
	          htmlScheme = repairAiHtmlScheme(
            {
              ...htmlScheme,
              correctionNotes: [
                ...(Array.isArray(htmlScheme.correctionNotes) ? htmlScheme.correctionNotes : []),
                `质量返修调用失败，保留已清洗自由 HTML：${cleanText(providerFailureSummary(error), "", 140)}`,
              ],
            },
            policyPayload,
	            homepageConfig,
	            resultProviderConfig,
		            { sourceType: htmlScheme.sourceType || "model/free-html", generationPipeline: "free-html-quality-gate", modelAttempted: true, mock: false },
		          );
        }
      }
	    } else {
	      try {
        const compactHtmlGeneration = providerUsesCompactAiHtml(resultProviderConfig);
		        const htmlResult = await callProviderWithPrompt(
		          htmlPayload,
		          aiHtmlPromptForProvider(resultProviderConfig, policyPayload, homepageConfig, { previousError: freeHtmlError }),
		          AI_HTML_SCHEME_JSON_SCHEMA,
		          compactHtmlGeneration ? `homepage_ai_html_${resultProviderConfig.provider}_compact` : "homepage_ai_html_repair",
		        );
	        htmlScheme = repairAiHtmlScheme(
	          {
	            ...htmlResult.json,
	            correctionNotes: [
	              compactHtmlGeneration
                  ? `${resultProviderConfig.name} 已使用短输出 AI HTML 通道，并参考组件库与配置契约生成。`
                  : `自由 HTML 首次生成失败，已改用配置参考修正版：${cleanText(providerFailureSummary(freeHtmlError), "", 120)}`,
	              ...(Array.isArray(htmlResult.json?.correctionNotes) ? htmlResult.json.correctionNotes : []),
	            ],
	          },
	          policyPayload,
	          homepageConfig,
	          resultProviderConfig,
			          {
                  sourceType: compactHtmlGeneration ? `model/${resultProviderConfig.provider}-ai-html` : "model-repair",
                  generationPipeline: compactHtmlGeneration ? `${resultProviderConfig.provider}-compact-ai-html` : "config-guided-repair",
                  modelAttempted: true,
                  mock: false,
                },
			          );
	        htmlUsage = htmlResult.usage || null;
	        htmlRawText = htmlResult.rawText || "";
	        htmlResponseJson = safeRecordJsonValue(htmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 });
	        if (compactHtmlGeneration && htmlScheme.qualityStatus === "needs-repair" && resultProviderConfig.provider !== "minimax") {
	          const compactQualityReport = evaluateAiHtmlQuality(htmlScheme, policyPayload, homepageConfig);
	          try {
	            const repairResult = await callProviderWithPrompt(
	              htmlPayload,
	              aiHtmlPromptForProvider(resultProviderConfig, policyPayload, homepageConfig, {
	                qualityReport: compactQualityReport,
	                previousScheme: htmlScheme,
	              }),
	              AI_HTML_SCHEME_JSON_SCHEMA,
	              `homepage_ai_html_${resultProviderConfig.provider}_quality_repair`,
	            );
	            const previousHtmlScheme = htmlScheme;
	            const repairedHtmlScheme = repairAiHtmlScheme(
	              {
	                ...repairResult.json,
	                correctionNotes: [
	                  `短输出 AI HTML 质量门禁 ${compactQualityReport.score}/100，已追加一次模型返修。`,
	                  ...(Array.isArray(compactQualityReport.issues) ? compactQualityReport.issues : []),
	                  ...(Array.isArray(repairResult.json?.correctionNotes) ? repairResult.json.correctionNotes : []),
	                ],
	              },
	              policyPayload,
	              homepageConfig,
	              resultProviderConfig,
	              {
	                sourceType: "model-repair",
	                generationPipeline: `${resultProviderConfig.provider}-compact-quality-repair`,
	                modelAttempted: true,
	                mock: false,
	              },
	            );
	            const previousScore = Number(previousHtmlScheme.qualityScore);
	            const repairedScore = Number(repairedHtmlScheme.qualityScore);
	            if (!Number.isFinite(previousScore) || !Number.isFinite(repairedScore) || repairedScore >= previousScore) {
	              htmlScheme = repairedHtmlScheme;
	            } else {
	              htmlScheme = {
	                ...previousHtmlScheme,
	                correctionNotes: [
	                  ...(Array.isArray(previousHtmlScheme.correctionNotes) ? previousHtmlScheme.correctionNotes : []),
	                  `短输出返修得分 ${repairedScore}/100 低于原方案 ${previousScore}/100，已保留原模型 HTML。`,
	                ].slice(0, 8),
	              };
	            }
	            htmlUsage = { compact: htmlResult.usage || null, repair: repairResult.usage || null };
	            htmlRawText = [htmlResult.rawText, repairResult.rawText].filter(Boolean).join("\n\n--- compact ai html quality repair ---\n\n");
	            htmlResponseJson = {
	              compact: safeRecordJsonValue(htmlResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	              repair: safeRecordJsonValue(repairResult.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	            };
	          } catch (repairError) {
	            htmlScheme = repairAiHtmlScheme(
	              {
	                ...htmlScheme,
	                correctionNotes: [
	                  ...(Array.isArray(htmlScheme.correctionNotes) ? htmlScheme.correctionNotes : []),
	                  `短输出质量返修调用失败，保留原模型 HTML：${cleanText(providerFailureSummary(repairError), "", 140)}`,
	                ],
	              },
	              policyPayload,
	              homepageConfig,
	              resultProviderConfig,
	              {
	                sourceType: htmlScheme.sourceType || `model/${resultProviderConfig.provider}-ai-html`,
	                generationPipeline: htmlScheme.generationPipeline || `${resultProviderConfig.provider}-compact-ai-html`,
	                modelAttempted: true,
	                mock: false,
	              },
	            );
	          }
	        }
		      } catch (error) {
        const failureSummary = providerFailureSummary(error || freeHtmlError);
        htmlScheme = configBackedAiHtmlScheme(policyPayload, homepageConfig, resultProviderConfig, {
          providerName: resultProviderConfig.name,
          sourceType: `model/${resultProviderConfig.provider}-config-html`,
          generationPipeline: `${resultProviderConfig.provider}-config-backed-html`,
          failureSummary,
          summary: `${resultProviderConfig.name} 已成功生成首页配置；AI HTML 长输出失败后，服务端改用配置蓝图装配可预览 HTML。`,
          visualBrief: "保留模型生成的首页意图、模块编排和主题，不再把 HTML 预览失败标记为整次生成回退。",
          correctionNotes: [
            freeHtmlError ? `自由 HTML 首次生成未采用：${cleanText(providerFailureSummary(freeHtmlError), "", 120)}` : "",
            `配置参考 HTML 未采用：${cleanText(providerFailureSummary(error), "", 120)}`,
          ].filter(Boolean),
        });
        htmlUsage = null;
        htmlRawText = "";
	      }
    }
  }

  if (
    renderModeWantsAiHtml(renderMode) &&
    htmlScheme?.enabled &&
    htmlScheme.sourceType !== "brick-library-backed" &&
    aiHtmlNeedsBrickBackedFallback(htmlScheme)
  ) {
    const brickBacked = brickBackedAiHtmlScheme(policyPayload, homepageConfig, resultProviderConfig, {
      modelAttempted: true,
      fallbackReason: `AI HTML 质量门禁 ${htmlScheme.qualityScore ?? "unknown"}/100 未达标，已启用高分积木同款保底。`,
      correctionNotes: [
        `上一版 AI HTML 质量状态：${htmlScheme.qualityStatus || "unknown"}。`,
        ...(Array.isArray(htmlScheme.qualityIssues) ? htmlScheme.qualityIssues.slice(0, 3) : []),
      ],
    });
    if (brickBacked) {
      htmlScheme = {
        ...brickBacked,
        correctionNotes: [
          ...(Array.isArray(brickBacked.correctionNotes) ? brickBacked.correctionNotes : []),
          "已用高分积木同款保底替换低质量 AI HTML，避免发布普通白卡片或空壳 HTML。",
        ].slice(0, 8),
      };
    }
  } else if (
    homeAiFaithfulMode() &&
    renderModeWantsAiHtml(renderMode) &&
    htmlScheme?.enabled &&
    htmlScheme.sourceType !== "brick-library-backed" &&
    !htmlScheme.isFallback &&
    Number.isFinite(Number(htmlScheme.qualityScore)) &&
    Number(htmlScheme.qualityScore) < homeAiFallbackMinScore()
  ) {
    // 忠实模式：分数低于门槛本应回退积木，但这里保留模型真实 HTML，仅做标注。
    htmlScheme = {
      ...htmlScheme,
      correctionNotes: [
        ...(Array.isArray(htmlScheme.correctionNotes) ? htmlScheme.correctionNotes : []),
        `忠实模式 (HOME_AI_FAITHFUL=true)：质量门禁 ${htmlScheme.qualityScore}/100 未达标，但保留模型真实 HTML、未启用积木同款兜底。`,
      ].slice(0, 8),
    };
  }

  const finalQuality = finalizeHomepageQuality(policyPayload, homepageConfig, htmlScheme);
  const finalConfig = {
    ...homepageConfig,
    validation: repaired.validation,
    validationWarnings: repaired.validation.warnings || [],
    modulePolicy,
    modulePolicyScore: finalQuality.modulePolicyScore,
    repairActions: repaired.repairActions,
    qualityScore: finalQuality.score,
    quality: finalQuality.quality,
    htmlQualityStatus: finalQuality.htmlQualityStatus,
    productWarnings: finalQuality.productWarnings,
  };

  return {
    config: {
      ...finalConfig,
      renderMode,
      htmlGenerationEnabled: renderModeWantsAiHtml(renderMode),
      skeletonHtmlEnabled: renderMode === "skeletonHtml",
      activeRenderMode: activeRenderModeForRequest(renderMode, htmlScheme),
      ...(htmlScheme ? { htmlScheme } : {}),
    },
    ...(htmlScheme ? { htmlScheme } : {}),
    validation: repaired.validation,
    validationWarnings: repaired.validation.warnings || [],
    modulePolicy,
    modulePolicyScore: finalQuality.modulePolicyScore,
    repairActions: repaired.repairActions,
    qualityScore: finalQuality.score,
    quality: finalQuality.quality,
    htmlQualityStatus: finalQuality.htmlQualityStatus,
    productWarnings: finalQuality.productWarnings,
    renderMode,
    activeRenderMode: activeRenderModeForRequest(renderMode, htmlScheme),
	    provider: result.provider,
	    model: result.model,
	    rawText: [result.rawText, htmlRawText].filter(Boolean).join("\n\n--- ai html ---\n\n"),
	    responseJson: {
	      homepageConfig: safeRecordJsonValue(result.json, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	      aiHtml: htmlResponseJson,
	      normalizedConfig: safeRecordJsonValue(finalConfig, { stringLimit: 60000, arrayLimit: 120, maxDepth: 9 }),
	    },
	    usage: htmlUsage ? { config: result.usage || null, html: htmlUsage } : result.usage,
	  };
	}

function buildComponentPromptForProvider(payload, config = {}) {
  if (providerUsesCompactComponentPrompt(config)) return buildMiniMaxComponentPrompt(payload, config);
  return buildComponentPrompt(payload);
}

function buildComponentEditPromptForProvider(payload, component, config = {}) {
  if (config.provider === "minimax") return buildMiniMaxComponentEditPrompt(payload, component, config);
  return buildComponentEditPrompt(payload, component);
}

function componentProviderCanUseLocalFallback(config, error) {
  const status = Number(error?.providerStatus || error?.details?.providerStatus || error?.statusCode);
  if ([400, 401, 403, 404].includes(status) && !/valid JSON object|Provider returned an empty/i.test(String(error?.message || ""))) {
    return false;
  }
  const details = error?.details || {};
  return (
    /valid JSON object|Provider returned an empty|timed out|timeout/i.test(String(error?.message || "")) ||
    Boolean(details.rawTextSnippet) ||
    Boolean(details.likelyTruncated) ||
    /length|max_tokens|content_filter/i.test(String(details.finishReason || ""))
  );
}

function componentProviderFallbackReason(error, fallback) {
  return cleanText(providerFailureSummary(error, fallback), fallback, 260);
}

function shouldPersistGeneratedComponent(payload = {}) {
  return payload.save !== false && payload.persist !== false && payload.draftOnly !== true;
}

function strictWelcomeHeaderFallbackComponent(payload = {}, providerConfig = {}) {
  const family = "WelcomeHeader";
  const size = normalizeComponentSize(payload.size, autoComponentSizeForPayload(payload, family));
  const root = safeId(`WelcomeHeader-strict-${Date.now().toString(36)}`, "ai-brick");
	  return normalizeGeneratedComponent(
	    {
	      name: "极简欢迎登录条",
      family,
      size,
      description: `只展示客户姓名、问候语和最近登录时间的欢迎头部。通过 ${providerConfig.name || "local"} / ${providerConfig.model || "fallback"} 兜底生成。`,
      tags: [family, size, "welcome", "last-login"],
      html: `<section class="${root}" aria-label="欢迎头部"><div><strong>早安，张明</strong><span>欢迎回来</span></div><p><small>最近登录时间</small><b>2026-05-20 09:41</b></p></section>`,
      css: `.${root}{min-height:128px;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px;border:1px solid var(--home-border);border-radius:var(--home-radius-sm,8px);background:var(--home-card-bg);color:var(--home-text);font-family:Inter,system-ui,sans-serif}.${root} *{box-sizing:border-box}.${root} div{display:grid;gap:6px}.${root} strong{color:var(--home-text-strong);font-size:26px;font-weight:950;letter-spacing:0}.${root} span,.${root} small{color:var(--home-text-muted);font-size:13px;font-weight:850}.${root} p{display:grid;gap:5px;min-width:220px;margin:0;padding:12px 14px;border:1px solid var(--home-border);border-radius:var(--home-radius-sm,8px);background:var(--home-surface-soft)}.${root} b{color:var(--home-text-strong);font-size:15px;font-weight:950}@media(max-width:720px){.${root}{align-items:stretch;flex-direction:column}.${root} p{min-width:0;width:100%}}`,
      layoutHints: [size, "轻量整行欢迎头部", "只展示姓名、问候和最近登录时间"],
	      dataRequirements: ["customerName", "greeting", "lastLoginAt"],
	    },
	    payload,
	    FRESH_GENERATED_COMPONENT_OPTIONS,
	  );
}

function componentProviderFallbackComponent(payload, config, reason, options = {}) {
  if (promptRequestsStrictWelcomeHeader(payload)) {
    const component = strictWelcomeHeaderFallbackComponent(payload, config);
    return {
      ...component,
      sourceType: "local-fallback",
      fallbackReason: reason,
    };
  }
  const brickFallback = componentLibraryFallbackForPayload(payload, { ...options, reason });
  if (brickFallback) return brickFallback;
  const component = mockGeneratedComponent(payload, config);
  const normalized = options.persist === false ? normalizeGeneratedComponent(component, payload) : saveComponent(component);
  return {
    ...normalized,
    sourceType: "local-fallback",
    fallbackReason: reason,
  };
}

async function callComponentProvider(payload) {
  const config = normalizeProviderConfig(payload.modelConfig);
  const persist = shouldPersistGeneratedComponent(payload);

  if (process.env.HOME_AI_MOCK === "true") {
    const component = mockGeneratedComponent(payload, config);
    return {
      component: persist ? saveComponent(component) : normalizeGeneratedComponent(component, payload),
      provider: config.provider,
      model: config.model,
      rawText: "",
      mock: true,
      saved: persist,
      draft: !persist,
    };
  }

  let result;
  try {
    result = await callProviderWithPrompt(payload, buildComponentPromptForProvider(payload, config), GENERATED_COMPONENT_JSON_SCHEMA, "homepage_component");
  } catch (error) {
    if (!componentProviderCanUseLocalFallback(config, error)) throw error;
    const reason = componentProviderFallbackReason(error, `${config.name} 输出不是可解析 JSON，已使用本地安全组件兜底。`);
    const component = componentProviderFallbackComponent(payload, config, reason, { persist });
    return {
      component,
      provider: config.provider,
      model: config.model,
      rawText: "",
      usage: null,
      localFallback: true,
      saved: persist && component.sourceType !== "brick-fallback",
      draft: !persist,
      fallbackSource: component.sourceType === "brick-fallback" ? "brick-library" : "local-template",
      fallbackReason: reason,
    };
	  }
		  const normalized = normalizeGeneratedComponent(result.json, payload, FRESH_GENERATED_COMPONENT_OPTIONS);
  const qualityIssues = generatedComponentQualityIssues(normalized, payload);
	  if (generatedComponentTooGeneric(normalized) || generatedComponentViolatesFamily(normalized, payload) || qualityIssues.length) {
	    const reason = qualityIssues.length
      ? `${config.name} 已返回组件，但质量门禁未通过：${qualityIssues[0]} 已引用积木库兜底。`
      : `${config.name} 已返回组件，但内容不符合当前 family 或业务字段要求，已引用积木库兜底。`;
	    const component = componentProviderFallbackComponent(payload, config, reason, { persist });
	    return {
	      component,
      provider: result.provider,
      model: result.model,
      rawText: result.rawText,
      usage: result.usage,
      localFallback: true,
	      saved: persist && component.sourceType !== "brick-fallback",
	      draft: !persist,
	      fallbackSource: component.sourceType === "brick-fallback" ? "brick-library" : "local-template",
	      fallbackReason: reason,
      qualityIssues,
	    };
	  }
	  const component = persist ? saveComponent(normalized) : normalized;
	  return {
	    component,
    provider: result.provider,
    model: result.model,
	    rawText: result.rawText,
	    usage: result.usage,
    qualityIssues: [],
	    saved: persist,
	    draft: !persist,
	  };
}

async function callComponentEditProvider(payload) {
  const config = normalizeProviderConfig(payload.modelConfig);
  const currentComponent = resolveComponentForEdit(payload);

  if (process.env.HOME_AI_MOCK === "true") {
    const component = saveComponent(mockEditedComponent(payload, currentComponent, config));
    return {
      component,
      provider: config.provider,
      model: config.model,
      rawText: "",
      mock: true,
    };
  }

  let result;
  try {
    result = await callProviderWithPrompt(payload, buildComponentEditPromptForProvider(payload, currentComponent, config), GENERATED_COMPONENT_JSON_SCHEMA, "homepage_component_edit");
  } catch (error) {
    if (!componentProviderCanUseLocalFallback(config, error)) throw error;
    const reason = componentProviderFallbackReason(error, `${config.name} 输出不是可解析 JSON，已使用本地安全编辑兜底。`);
    const fallbackPayload = {
      ...payload,
      prompt: payload.instruction || currentComponent.sourcePrompt || currentComponent.description,
      family: currentComponent.family,
      size: currentComponent.size,
    };
    const component = componentProviderFallbackComponent(fallbackPayload, config, reason, { excludeIds: [currentComponent.id] });
    return {
      component,
      provider: config.provider,
      model: config.model,
      rawText: "",
      usage: null,
      localFallback: true,
      fallbackSource: component.sourceType === "brick-fallback" ? "brick-library" : "local-template",
      fallbackReason: reason,
    };
  }
  const sourcePrompt = cleanText(currentComponent.sourcePrompt, "", 500);
	  const normalized = normalizeGeneratedComponent(
	    {
	      ...currentComponent,
      ...result.json,
      id: currentComponent.id,
      createdAt: currentComponent.createdAt,
    },
    {
      ...payload,
      family: result.json.family || currentComponent.family,
	      size: result.json.size || currentComponent.size,
	      prompt: sourcePrompt,
	    },
	    FRESH_GENERATED_COMPONENT_OPTIONS,
		  );
	  const violatesFamily = generatedComponentViolatesFamily(normalized, { ...payload, family: currentComponent.family });
  const qualityIssues = generatedComponentQualityIssues(normalized, { ...payload, family: currentComponent.family });
	  if (generatedComponentTooGeneric(normalized) || violatesFamily || qualityIssues.length) {
	    const reason = violatesFamily
	      ? `${config.name} 已返回编辑结果，但偏离原组件 family，已引用同类积木兜底。`
	      : qualityIssues.length
          ? `${config.name} 已返回编辑结果，但质量门禁未通过：${qualityIssues[0]} 已引用组件库积木兜底。`
          : `${config.name} 已返回编辑结果，但内容过于通用，已引用组件库积木兜底。`;
	    const fallbackPayload = {
	      ...payload,
	      prompt: payload.instruction || currentComponent.sourcePrompt || currentComponent.description,
      family: currentComponent.family,
      size: currentComponent.size,
    };
    const component = componentProviderFallbackComponent(fallbackPayload, config, reason, { excludeIds: [currentComponent.id] });
    return {
      component,
      provider: result.provider,
      model: result.model,
      rawText: result.rawText,
      usage: result.usage,
	      localFallback: true,
	      fallbackSource: component.sourceType === "brick-fallback" ? "brick-library" : "local-template",
	      fallbackReason: reason,
      qualityIssues,
	    };
	  }
	  const component = saveComponent(normalized);
  return {
    component,
    provider: result.provider,
	    model: result.model,
	    rawText: result.rawText,
	    usage: result.usage,
    qualityIssues: [],
	  };
	}

